"use strict";
/* ================= ER DEEP DIVES (history, etymology, culture, anatomy, 2026 context) ================= */
const DEEP={"jvp": {"hist": "Sir Thomas Lewis, the London cardiologist, published 'Remarks on early signs of cardiac failure of the congestive type' in the BMJ in 1930, arguing that distended neck veins are the earliest sign of congestive failure and that the jugular veins act as a manometer for right atrial pressure. He described the pressure qualitatively ('normal', 'raised a little') and never published a fixed number. The familiar convention that the sternal angle sits about 5 cm above the right atrium was attributed to him later, notably by Paul Allen in 1948 ('the 5-centimeter constant of Lewis') and by his pupil Paul Wood in 1957.", "etym": "Jugular comes from the Latin jugulum, the collarbone or throat, a diminutive of jugum, a yoke, because the collarbones sit across the neck like a yoke. 'Venous' is from vena, a vein.", "culture": "The 'Lewis method' of adding 5 cm to the height above the sternal angle is named after a technique Lewis never actually published. A 2002 CT study of 160 patients (Seth et al.) found the sternal angle about 5 cm above the right atrium lying flat, but the distance grew as patients sat up (about 8 cm at 30° and more at 45–60°), so the folklore '5 cm' underestimates right atrial pressure in a propped-up patient. The practical lesson stands: a JVP more than 3 cm above the sternal angle is raised.", "anat": "The right internal jugular vein runs in an almost straight, functionally valveless line into the superior vena cava and right atrium, so the top of its blood column is a direct gauge of right atrial pressure. Because it lies deep to sternocleidomastoid you usually see its transmitted pulsation, not the vein itself; the waveform shows an a wave (atrial contraction), x descent (atrial relaxation and descent of the tricuspid ring), v wave (atrial filling against a closed tricuspid valve) and y descent (tricuspid opening). Normally the column falls on inspiration as negative intrathoracic pressure draws blood into the chest. Raised JVP means the right heart cannot accept venous return: right or left heart failure, fluid overload, tricuspid disease, tamponade, constriction, massive PE or tension pneumothorax.", "context": "In the 2026 ED the JVP is a fast bedside discriminator in breathlessness, shock and oedema: a raised JVP in hypotension points towards obstructive or cardiogenic shock rather than hypovolaemia or distributive shock. It is now routinely cross-checked with POCUS: a plethoric non-collapsing IVC, internal jugular vein distension on a linear probe, B-lines and the echo window. In one study of chronic heart failure a raised resting JVP had about 57% sensitivity and 93% specificity for a high wedge pressure, so it is better at ruling in than ruling out congestion.", "pearls": ["Position the patient so you can see the top of the column, not at a fixed 45 degrees; a very high JVP is missed when the patient lies flat and a low one when sitting upright.", "Venous pulsation is double-peaked, non-palpable, occludable with light pressure at the root of the neck, varies with respiration and position; the carotid is single, palpable and does not move with posture.", "Use tangential light from the side and ask the patient to turn the head slightly away; the external jugular is a legitimate manometer if it is not kinked.", "Sustained abdominal pressure for 10 to 15 seconds raising the JVP by 3 cm or more (abdominojugular test) unmasks right heart congestion.", "Giant v waves suggest tricuspid regurgitation; irregular cannon a waves suggest AV dissociation such as complete heart block or VT."], "pitfalls": ["Mistaking the carotid pulse for the venous column, especially in thin, hyperdynamic patients.", "Calling the JVP 'not seen' when it is actually so high that the top is above the jaw angle with the patient semi-recumbent; sit them bolt upright and look at the ear lobes.", "Treating a normal JVP as proof of euvolaemia in a ventilated, obese or very breathless patient in whom it cannot be reliably assessed."], "hook": "Picture the neck as Lewis's water gauge on the side of a boiler: the higher the water climbs up the glass, the more the right heart is drowning.", "sources": ["https://hekint.org/2021/06/14/remembering-sir-thomas-lewis-contribution-to-understanding-heart-failure/", "https://www.mja.com.au/journal/2010/193/1/measurement-jugular-venous-pressure"]}, "pulsus-paradoxus": {"hist": "Adolf Kussmaul described the paradoxical pulse in 1873 in 'Über schwielige Mediastino-Perikarditis und den paradoxen Puls' (Berliner klinische Wochenschrift 10:433 to 435), in patients with what we would now call constrictive (callous) mediastinopericarditis. He noted that the radial pulse became smaller or vanished entirely during inspiration and returned on expiration. In the same paper he described inspiratory swelling of the neck veins, now Kussmaul's sign.", "etym": "Paradoxus is Latin from the Greek paradoxos, contrary to expectation (para, beyond, and doxa, opinion). Kussmaul called it paradoxical because the peripheral pulse disappeared while the heartbeat itself continued strongly and regularly.", "culture": "The name is itself a misnomer: the sign is not a paradox at all but an exaggeration of the normal small inspiratory fall in systolic pressure, which is under 10 mmHg in health. Kussmaul also noted that the pulse could seem irregular while actually following a strict respiratory pattern, an early lesson in looking for rhythm within apparent chaos.", "anat": "On inspiration negative intrathoracic pressure increases venous return to the right ventricle while blood pools in the expanding pulmonary veins. When the pericardium is tight (tamponade) the two ventricles share a fixed volume, so the right ventricle can only fill by pushing the septum into the left ventricle, shrinking left ventricular filling and stroke volume. The same exaggerated swings in intrathoracic pressure in severe asthma or COPD produce pulsus paradoxus without pericardial disease. A fall in systolic pressure of more than 10 mmHg on inspiration is abnormal; more than 20 mmHg is severe.", "context": "Its main ED use is in a patient with a known or suspected pericardial effusion and in severe acute asthma, where a large pulsus reflects work of breathing. In the JAMA Rational Clinical Examination review (Roy 2007), pulsus paradoxus over 10 mmHg had about 82% sensitivity for tamponade and over 12 mmHg had a positive likelihood ratio of about 5.9, with a negative likelihood ratio of about 0.03, making it the most useful bedside sign. In 2026 echocardiography (right atrial systolic collapse, right ventricular diastolic collapse, plethoric IVC, respiratory variation in mitral inflow) is the decisive test, but a measured pulsus still guides urgency.", "pearls": ["Measure it: inflate the cuff above systolic, deflate slowly, note when Korotkoff sounds first appear only in expiration, then when they are heard in every beat; the difference is the pulsus.", "An arterial line or the pulse oximeter plethysmograph waveform shows the respiratory swing visually.", "A palpable paradoxical pulse (radial disappears on inspiration) usually means a pulsus well over 20 mmHg.", "Tamponade can occur without pulsus paradoxus in atrial septal defect, severe aortic regurgitation, severe left ventricular hypertrophy, or regional (post-operative) tamponade."], "pitfalls": ["Asking the patient to take big deliberate breaths, which exaggerates the normal variation and creates false positives.", "Relying on it during positive pressure ventilation, where the physiology reverses and the sign becomes unreliable.", "Measuring too quickly with an automated cuff, which cannot detect the beat-to-beat variation."], "hook": "Two brothers sharing one tight sleeping bag: when the right brother breathes in and expands, the left one gets squeezed and his voice (the pulse) goes quiet.", "sources": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC2757428", "https://litfl.com/adolph-kussmaul", "https://scholar.harvard.edu/sites/scholar.harvard.edu/files/nkc/files/2007_tamponade_rce_jama.pdf", "https://www.aliem.com/paucis-verbis-cardiac-tamponade-or-just-an-effusion/"]}, "tamponade-signs": {"hist": "Claude Schaeffer Beck, a cardiac surgeon in Cleveland, published 'Two cardiac compression triads' in JAMA in 1935 (104:714 to 716), building on a 1934 paper with E. H. Cushing on chronic pericardial compression. The acute compression triad was falling arterial pressure, rising venous pressure and a small, quiet heart; the chronic triad was high venous pressure, ascites and a small quiet heart. The acute triad was derived from surgical tamponade such as cardiac wounds and rupture.", "etym": "Tamponade comes from the French tampon, a plug or stopper, describing the heart being plugged by fluid in a closed sac. Triad is from the Greek trias, a group of three.", "culture": "Beck was far more than a triad: in 1947 he performed the first successful defibrillation of a human heart, restoring a 14-year-old boy in ventricular fibrillation during surgery after open cardiac massage and shocks, and he went on to train thousands of doctors and nurses in resuscitation. Ironically his triad, beloved of examiners, is present in only a minority of real tamponade cases, especially in medical (slow) effusions.", "anat": "The parietal pericardium is fibrous and poorly distensible in the short term, so the pressure-volume curve is flat and then suddenly steep: a small extra volume after a critical point causes a large pressure rise. Once intrapericardial pressure exceeds diastolic filling pressures, the thin-walled right atrium and ventricle collapse first, venous return falls, cardiac output drops and systemic venous pressure rises. Slowly accumulating effusions stretch the pericardium and can reach a litre or more before tamponade; acute haemopericardium can tamponade with 100 to 200 mL. Muffled heart sounds and a quiet heart reflect fluid insulating and restricting cardiac motion.", "context": "In 2026 tamponade is diagnosed clinically plus POCUS, not by triad alone: look for effusion with right atrial systolic collapse, right ventricular diastolic collapse, a plethoric IVC and exaggerated respiratory variation in inflow. The JAMA review (Roy 2007) found hypotension in only about 26% and diminished heart sounds in about 28% of medical tamponade, while dyspnoea, tachycardia, raised JVP and pulsus paradoxus were far more sensitive. Trauma (eFAST cardiac view), post-cardiac procedure, malignancy, uraemia and aortic dissection are the key ED settings; treatment is pericardiocentesis or surgical drainage, not inotropes.", "pearls": ["Tachycardia is near universal; a tamponade patient who is not tachycardic should make you question the diagnosis or look for beta-blockade or hypothyroidism.", "Look at the neck before the chest: a raised JVP with an absent y descent is classic.", "Patients with chronic hypertension can be normotensive or even hypertensive while in tamponade physiology.", "In a stabbed or post-procedure patient with PEA, the pericardium is the first place to scan.", "Small fluid boluses may buy time; positive pressure ventilation can precipitate arrest, so drain first if you can."], "pitfalls": ["Waiting for all three elements of Beck's triad before acting.", "Assuming a small effusion cannot cause tamponade: rate of accumulation matters more than size.", "Giving diuretics for a raised JVP and breathlessness without looking for an effusion."], "hook": "A balloon in a cast: the cast fills, the balloon cannot expand, so pressure backs up behind it (high JVP) and nothing comes out in front (low BP), all with a muffled thud.", "sources": ["https://litfl.com/claude-beck/", "https://scholar.harvard.edu/sites/scholar.harvard.edu/files/nkc/files/2007_tamponade_rce_jama.pdf", "https://www.aliem.com/paucis-verbis-cardiac-tamponade-or-just-an-effusion/"]}, "kussmaul-breathing": {"hist": "Adolf Kussmaul described this breathing pattern in 1874 in 'Zur Lehre vom Diabetes mellitus' (Deutsches Archiv für klinische Medicin 14:1 to 46), in which he examined a peculiar form of death in diabetic patients. He described deep, laboured breathing preceding coma and death in advanced diabetes, which he called air hunger (Lufthunger). An English translation appears in R. H. Major's 'Classic Descriptions of Disease'.", "etym": "Named after Adolf Kussmaul (1822 to 1902), whose surname is also spelled Kußmaul. 'Air hunger' translates his German Lufthunger, describing the patient's seemingly involuntary drive to breathe deeply.", "culture": "Kussmaul had a playful side: with his friend Ludwig Eichrodt he wrote comic verse under the pseudonym 'Gottlieb Biedermaier', a name that gave the Biedermeier period of German culture its label. He also built an early ophthalmoscope and joked it was the best in the world because it was the only one, even though it did not work.", "anat": "Metabolic acidosis lowers blood and cerebrospinal fluid pH, stimulating peripheral (carotid body) and central chemoreceptors to increase minute ventilation and blow off carbon dioxide. The increase comes mainly from large tidal volumes rather than a high rate, giving deep, sighing breaths that can look calm and regular. Expected compensation follows Winter's formula: expected PaCO2 is about 1.5 times bicarbonate plus 8 (plus or minus 2). DKA is the classic cause, but uraemia, lactic acidosis, salicylate, methanol and ethylene glycol poisoning do the same.", "context": "In the 2026 ED it is a cue to check a venous gas, glucose, ketones and lactate immediately; it often precedes the diagnosis of DKA in a 'chest infection' or 'gastroenteritis'. Measure whether compensation is appropriate with Winter's formula: a PaCO2 higher than predicted means an additional respiratory acidosis and impending fatigue. Intubating such a patient is high risk, because failing to match their pre-intubation minute ventilation causes rapid, sometimes fatal, worsening of acidosis.", "pearls": ["Count the depth, not just the rate: the respiratory rate can be normal while the tidal volume is enormous.", "Smell the breath: ketones (pear drops) suggest DKA; uraemic fetor suggests renal failure.", "A falling PaCO2 that stops falling or begins to rise in a tiring patient is a warning sign of respiratory failure.", "If you must intubate, set a high minute ventilation to match their pre-intubation PaCO2."], "pitfalls": ["Labelling deep breathing as anxiety or hyperventilation syndrome without a blood gas.", "Treating with oxygen for 'shortness of breath' and missing a metabolic cause because SpO2 is normal.", "Giving bicarbonate reflexively instead of treating the underlying acidosis."], "hook": "Kussmaul breathing is the body's bellows pumping acid out as CO2: deep, slow, relentless sighs from a furnace trying to cool itself.", "sources": ["https://en.wikipedia.org/wiki/Kussmaul_breathing", "https://litfl.com/adolph-kussmaul"]}, "kussmaul-sign": {"hist": "Kussmaul described the sign in the same 1873 paper as pulsus paradoxus ('Über schwielige Mediastino-Perikarditis und den paradoxen Puls', Berliner klinische Wochenschrift). He observed that in constrictive mediastinopericarditis the jugular veins were considerably swollen and their contents increased slightly with each inspiration. Some historians note that Wilhelm Griesinger had observed inspiratory venous swelling earlier, in 1854.", "etym": "Named after Adolf Kussmaul. 'Sign' derives from the Latin signum, a mark or token.", "culture": "Kussmaul's name is on three famous findings (pulsus paradoxus, this sign and acidotic breathing), and he is also credited with early attempts at oesophagoscopy and gastroscopy. Students often confuse Kussmaul's sign with Kussmaul breathing; one is in the neck veins, the other in the chest.", "anat": "Normally inspiration lowers intrathoracic pressure, the right heart accepts the extra venous return, and the JVP falls. When the right heart cannot accept more volume because of a rigid pericardium, stiff myocardium or a failing right ventricle, the extra venous return has nowhere to go and the JVP paradoxically rises or fails to fall. Constrictive pericarditis is the classic cause, together with restrictive cardiomyopathy, right ventricular infarction, severe right heart failure, massive PE and tricuspid stenosis. It is classically absent in tamponade, because fluid transmits the inspiratory fall in intrathoracic pressure to the heart.", "context": "In the ED its practical value is in inferior STEMI: a raised JVP with Kussmaul's sign and clear lungs suggests right ventricular involvement, prompting right-sided ECG leads and caution with nitrates and diuretics. In unexplained right heart failure or ascites with a high JVP, it points towards constriction or restriction, which needs echocardiography, and often cardiac MRI or CT and invasive haemodynamics, to diagnose. Bedside echo showing septal bounce and respiratory variation supports constriction.", "pearls": ["Watch the top of the column over several quiet breaths; the patient should breathe normally, not forcefully.", "Kussmaul's sign plus a steep y descent (Friedreich's sign) strongly suggests constriction.", "Inferior STEMI with hypotension, a high JVP and clear lungs is right ventricular infarction until proven otherwise; give fluid cautiously and avoid nitrates."], "pitfalls": ["Using it to diagnose tamponade, where it is usually absent.", "Confusing it with Kussmaul breathing.", "Missing it because the patient is lying too flat for the top of the column to be seen."], "hook": "Breathing in should drain the neck like pulling a plug; if the neck fills instead, the drain (the right heart) is blocked.", "sources": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC2757428", "https://en.wikipedia.org/wiki/Kussmaul%27s_sign", "https://litfl.com/adolph-kussmaul"]}, "shock-index": {"hist": "The shock index was introduced by Martin Allgöwer and Carl Burri in 1967 in 'Schockindex' (Deutsche Medizinische Wochenschrift 92:1947 to 1950), followed by an English-language version in German Medical Monthly in 1968. They proposed heart rate divided by systolic blood pressure as a simple estimate of blood loss and severity of hypovolaemic shock. Allgöwer was a Swiss surgeon based in Basel.", "etym": "Shock in the medical sense comes via the French choc, a violent blow or collision. Index is Latin for a pointer or indicator.", "culture": "Allgöwer is better known to orthopaedic surgeons as a co-founder of the AO (Arbeitsgemeinschaft für Osteosynthesefragen) foundation in 1958, which transformed fracture fixation. The shock index lay relatively quiet for decades before becoming a staple of trauma triage, obstetric haemorrhage tools and early warning research.", "anat": "In early haemorrhage, baroreceptor reflexes raise heart rate and peripheral resistance, keeping systolic pressure in the normal range while stroke volume and cardiac output fall. Dividing heart rate by systolic pressure exposes this compensated phase, because the ratio rises before either value crosses its alarm threshold. Normal is about 0.5 to 0.7; values of 1.0 or more indicate significant shock and are associated with transfusion need and mortality.", "context": "In 2026 the shock index is used in trauma and obstetric triage and in sepsis and GI bleeding risk stratification as a quick number at the door; trauma studies (for example Mutschler 2013) grade shock as SI under 0.6, 0.6 to 1.0, 1.0 to 1.4 and 1.4 or more. Variants include the obstetric shock index (threshold around 0.9 to 1.0 in pregnancy), the age shock index (age multiplied by SI) and reverse shock index. It supplements, not replaces, lactate, base deficit, POCUS (eFAST, IVC, cardiac function) and clinical gestalt.", "pearls": ["Calculate it at triage and again after each intervention; the trend tells you more than one value.", "An SI of 1.0 or more in a normotensive patient means they are compensating, not that they are fine.", "In pregnancy physiological tachycardia raises the normal range, so use obstetric thresholds.", "An SI rising after fluids suggests ongoing bleeding and the need for blood and source control."], "pitfalls": ["Being falsely reassured in patients on beta-blockers, with pacemakers, or in the elderly, who may not mount a tachycardia.", "Overcalling shock in pain, anxiety, fever or chronic hypertension (where a 'normal' systolic may already be relative hypotension).", "Using a single number as a disposition decision."], "hook": "The heart rate is the alarm bell and the systolic pressure is the dam wall: when the bell rings louder than the wall is high (ratio above 1), the flood is already coming.", "sources": ["https://ccforum.biomedcentral.com/track/pdf/10.1186/cc12851", "https://www.omnicalculator.com/health/shock-index"]}, "cap-refill": {"hist": "Henry Beecher and colleagues described a blanching test in 1947 in their study of wounded soldiers ('Resuscitation of men severely wounded in battle'), pressing the nail bed for about 10 seconds and grading the return of colour as normal, definitely slowed or very sluggish. Howard Champion and colleagues included capillary refill in the Trauma Score in 1980 to 1981 and proposed under 2 seconds as normal. Schriger and Baraff (Annals of Emergency Medicine, 1988) showed that normal values vary with age, sex and temperature.", "etym": "Capillary comes from the Latin capillaris, 'hair-like', from capillus, a hair, because the vessels are hair-thin. Refill is simply refilling of the blanched skin with blood.", "culture": "The famous 2-second cut-off has been described as arbitrarily chosen by a nurse in Champion's team, with no data behind it; Schriger and Baraff found upper limits of about 2.9 seconds in adult women and 4.5 seconds in the elderly. Yet in a remarkable revival, ANDROMEDA-SHOCK-2 (JAMA 2025, 1,501 patients) found CRT-targeted, phenotype-based resuscitation of septic shock improved a hierarchical outcome (win ratio 1.16) compared with usual care, though 28-day mortality was similar.", "anat": "Pressing the skin empties the capillary bed and subpapillary venous plexus; on release, refilling depends on arterial inflow, precapillary sphincter tone and local sympathetic vasoconstriction. In hypovolaemia and septic shock with poor perfusion, sympathetic activation constricts skin arterioles first, sacrificing skin to protect vital organs, so refill slows. Cold ambient temperature, age, ambient light, pressure applied and site all change the result.", "context": "In children it remains a core sign in NICE fever and sepsis guidance (3 seconds or more is an amber or worse feature) and in paediatric triage. In adults it is a simple, repeatable perfusion marker in septic shock, supported by ANDROMEDA-SHOCK (2019), which compared it with lactate-targeted resuscitation, and ANDROMEDA-SHOCK-2 (2025). In haemorrhage it is insensitive: in the McGee JAMA 1999 review it had only about 6% sensitivity for 450 mL blood loss. Use it alongside mottling score, lactate, mental state, urine output and POCUS.", "pearls": ["Standardise technique: press the fingertip pulp (or sternum in infants) firmly for 5 seconds at heart level, then count aloud or use a timer.", "A warm room and a warm hand matter; slow refill in a cold patient is not necessarily shock.", "Use central CRT (sternum or forehead) in children; peripheral CRT is affected by ambient temperature.", "Trend it every 30 minutes during sepsis resuscitation; normalisation is reassuring."], "pitfalls": ["Using a strict 2-second threshold in older adults, in whom normal CRT can be up to about 4.5 seconds.", "Estimating time by eye rather than counting; interobserver variability can be around 2 seconds.", "Being reassured by a normal CRT in early haemorrhage."], "hook": "Press the fingertip like a doorbell: if the house (circulation) answers slowly, someone is in trouble inside.", "sources": ["https://en.wikipedia.org/wiki/Capillary_refill", "https://www.crisis-medicine.com/capillary-refill-time-theoretical-but-not-sound/", "https://criticalcarereviews.com/foundational-trials/andromeda-shock-2", "https://www.aafp.org/pubs/afp/issues/1999/0915/p1220a.html"]}, "postural": {"hist": "The formal definition of orthostatic hypotension, a systolic fall of at least 20 mmHg or diastolic fall of at least 10 mmHg within 3 minutes of standing, was set by a 1996 consensus statement of the American Autonomic Society and the American Academy of Neurology. The bedside evidence for postural vital signs in hypovolaemia was summarised by McGee, Abernethy and Simel in the JAMA Rational Clinical Examination series in 1999 ('Is this patient hypovolemic?'), largely using studies of blood donors and phlebotomy.", "etym": "Postural comes from the Latin positura, position. Orthostatic comes from the Greek orthos, upright or straight, and statos, standing.", "culture": "Much of what we know about postural vitals comes from healthy volunteers who had a known volume of blood removed, a rare example of a bedside sign calibrated against a precisely measured 'disease'. McGee's analysis showed that the traditional focus on the blood pressure drop was misplaced: the postural pulse rise and severe postural dizziness were the useful findings.", "anat": "On standing roughly 500 to 800 mL of blood pools in the legs and splanchnic veins, reducing venous return and stroke volume. The baroreflex responds within seconds with tachycardia and vasoconstriction, keeping blood pressure stable. When intravascular volume is low the reflex cannot compensate fully, so heart rate rises sharply and pressure falls; when the autonomic nervous system itself fails (diabetes, Parkinson disease, drugs) pressure falls without a compensatory tachycardia.", "context": "In the ED, postural vitals help in suspected occult blood loss, dehydration and syncope work-up. In McGee's review, a postural pulse increase of 30 beats per minute or more, or severe postural dizziness preventing upright measurement, had about 97% sensitivity and 98% specificity for large blood loss (about 630 to 1150 mL) but was poor for moderate loss. The ESC syncope guidance uses active standing to diagnose orthostatic hypotension. In 2026 they are supplemented by POCUS (IVC, cardiac function), passive leg raise testing, lactate and haemoglobin trends.", "pearls": ["Measure supine after at least 2 to 5 minutes, then standing (not just sitting) at 1 and 3 minutes.", "Use the heart rate rise (30 or more per minute) for hypovolaemia; the BP fall is common in healthy older people.", "If the patient cannot stand because of dizziness, that is itself a positive result.", "A large BP fall with no heart rate rise suggests autonomic failure or beta-blockade rather than volume loss."], "pitfalls": ["Measuring only sitting, which underestimates the response.", "Standing an obviously shocked or syncopal patient, risking injury; supervise and stop if symptomatic.", "Labelling orthostatic hypotension in an older patient as dehydration without considering drugs and autonomic neuropathy."], "hook": "Standing up is a gravity stress test: a full tank pours steadily, an empty tank makes the pump race (pulse up 30) before it sputters.", "sources": ["https://www.aafp.org/pubs/afp/issues/1999/0915/p1220a.html", "https://www.aafp.org/pubs/afp/issues/2003/1215/p2393.html"]}, "bp-arms": {"hist": "One of the earliest detailed accounts of aortic dissection is Frank Nicholls's autopsy of King George II, who died on 20 October 1760; Nicholls found a pericardium full of clotted blood and a tear in the aorta, later published in the Philosophical Transactions of the Royal Society. The modern evidence for pulse and blood pressure differentials comes from studies such as von Kodolitsch and colleagues (Archives of Internal Medicine, 2000), who identified abrupt tearing pain, mediastinal widening and pulse or blood pressure differentials as independent predictors. The Aortic Dissection Detection Risk Score (ADD-RS), derived from the 2010 American thoracic aortic disease guidelines, includes perfusion deficit as a high-risk examination feature.", "etym": "Dissection is from the Latin dissecare, to cut apart; the blood literally cuts the aortic wall into two layers. Aorta comes from the Greek aorte, from aeirein, to lift or raise up.", "culture": "George II is said to have collapsed while straining on the close stool, making him one of history's best-documented cases of aortic dissection and a perennial teaching anecdote. In modern EDs aortic dissection is one of the most commonly missed diagnoses, often mislabelled as ACS, renal colic or musculoskeletal pain, which is why examination signs and risk scores have been promoted so strongly.", "anat": "In type A or arch dissection the false lumen or intimal flap can extend into or compress the brachiocephalic or left subclavian artery, reducing flow and pressure to one arm. The result is an inter-arm systolic difference, a weaker radial or brachial pulse, or a carotid or femoral deficit. Because it depends on which branches are involved, the sign is present in only a minority (roughly 15 to 30%) of dissections, and a modest inter-arm difference is common in healthy people and in subclavian atherosclerosis.", "context": "Check both arms and all four limbs in any patient with chest, back or abdominal pain plus syncope, neurological deficit or hypotension. A systolic difference of more than 20 mmHg (Um and colleagues, EMJ 2018) and especially a pulse deficit raise the probability of dissection, but their absence never excludes it. In 2026 practice the ADD-RS combined with D-dimer (ADvISED study, Circulation 2018) is used to select low-risk patients, while CT angiography is the definitive test; bedside echo may show a flap, aortic root dilatation, aortic regurgitation or pericardial effusion. Titrate antihypertensives to the higher arm reading.", "pearls": ["Measure both arms simultaneously or in quick succession with the same cuff size; repeat if the first difference is borderline.", "Feel radial, carotid and femoral pulses on both sides together, not one after the other minutes apart.", "Pain plus a new neurological deficit, a new aortic regurgitation murmur or a pulse deficit should trigger CT angiography.", "Use the higher arm BP for management; the lower arm may give pseudohypotension."], "pitfalls": ["Assuming no pulse deficit means no dissection.", "Overcalling a 10 to 15 mmHg difference that is common in healthy patients or peripheral arterial disease.", "Thrombolysing or giving full anticoagulation for presumed ACS or stroke without considering dissection."], "hook": "A dissection is a burst pipe inside a pipe: if the flap closes the tap to one arm, that arm's pressure gauge drops.", "sources": ["https://royalsociety.org/blog/2020/02/dissecting-a-king/", "https://www.aliem.com/blood-pressure-differences-patients-acute-aortic-dissections/", "https://litfl.com/aortic-dissection-detection-risk-score-add-rs/", "https://fis.uke.de/portal/en/publications/clinical-prediction-of-acute-aortic-dissection(d35b0e9a-30c5-4ee1-832e-c4ae921a1085)/export.html"]}, "homans": {"hist": "John Homans (1877 to 1954), a Boston surgeon trained at Harvard and Massachusetts General Hospital, wrote about calf vein thrombosis causing pulmonary embolism in the New England Journal of Medicine in 1934. In 1941 (NEJM 224:179 to 186, 'Exploration and division of the femoral and iliac veins in the treatment of thrombophlebitis of the leg') he described 'discomfort behind the knee on forced dorsiflexion of the foot'. After many false positives were reported, he redefined it in 1944, stating that 'discomfort need have no part in the reaction'.", "etym": "An eponym from John Homans; the correct spelling is Homans' sign (or Homans sign), not 'Homan's sign'. Dorsiflexion combines the Latin dorsum, back, and flectere, to bend.", "culture": "Homans himself became uneasy at how the sign was used, broadening its definition within three years, yet it survived for decades in textbooks, exam answers and nursing checklists. It is one of a long list of near-forgotten DVT eponyms (Payr, Pratt, Lowenberg, Mahler, Meyer and others), and is now often taught mainly as an example of a sign that persisted out of tradition rather than evidence.", "anat": "Forced dorsiflexion stretches gastrocnemius and soleus and compresses the deep calf veins, so a thrombosed, inflamed vein may hurt. But the same manoeuvre stretches any painful calf: muscle strain, Baker cyst, cellulitis, lumbar radiculopathy, so specificity is poor. Many DVTs, especially proximal ones and those in non-ambulant patients, are not tender at all, so sensitivity is poor too.", "context": "Homans' sign is obsolete in 2026 practice: estimated sensitivity 10 to 54% and specificity 39 to 89% mean a positive does not rule DVT in and a negative does not rule it out. Suspected DVT is managed with a structured pretest probability (two-level Wells), D-dimer in unlikely patients, and compression ultrasound, including emergency physician POCUS two- or three-point compression. The theoretical worry about dislodging clot is a further reason not to do forceful manoeuvres.", "pearls": ["Replace it with the Wells score and compression ultrasound; document the Wells components instead.", "Measure calf circumference 10 cm below the tibial tuberosity: a difference over 3 cm is a Wells item, Homans' is not.", "Calf pain on dorsiflexion is more often musculoskeletal or a ruptured Baker cyst; ultrasound sorts both."], "pitfalls": ["Writing 'Homans negative' as if it reduces DVT probability.", "Misspelling it as 'Homan's sign' in notes and exams."], "hook": "Homans' sign is the museum piece of DVT diagnosis: admire the history behind the glass, but use the ultrasound probe in the next room.", "sources": ["https://en.wikipedia.org/wiki/Homans_sign", "https://redux.whonamedit.com/synd.cfm/2371.html", "https://www.thebloodproject.com/eponymic-physical-signs-in-deep-vein-thrombosis/"]}, "wells-pe": {"hist": "Philip Wells and colleagues in Ottawa published a clinical model for pulmonary embolism in the Annals of Internal Medicine in 1998 (129:997 to 1005), built on their 1995 DVT work and originally presented as an algorithm. In 2000 they published a numerical score combined with the SimpliRED D-dimer in Thrombosis and Haemostasis (83:416 to 420), with three-tier and two-tier (PE likely if more than 4) versions. Jeffrey Kline and colleagues derived the Pulmonary Embolism Rule-out Criteria (PERC) in 2004 (Journal of Thrombosis and Haemostasis) from 3,148 ED patients at 10 US sites.", "etym": "Wells is an eponym; PERC is an acronym for Pulmonary Embolism Rule-out Criteria. Embolism is from the Greek embolos, a plug or wedge, from emballein, to throw in.", "culture": "The most heavily weighted Wells item, 'an alternative diagnosis is less likely than PE', worth 3 points, is entirely subjective, so the 'objective' score partly encodes the clinician's gut feeling. The cluster-randomised PROPER trial (Freund, JAMA 2018, 1,916 patients in 14 French EDs) showed that using PERC alone in low-risk patients was non-inferior and reduced CT use from 23% to 13%.", "anat": "Wells and PERC items each reflect a piece of Virchow's triad or the physiological consequence of clot in the lungs: immobility and surgery (stasis), malignancy, oestrogen and previous VTE (hypercoagulability), leg signs (the source), tachycardia, hypoxia and haemoptysis (effect on the pulmonary circulation). PERC's eight criteria are age 50 or over, heart rate 100 or over, SpO2 under 95% on air, unilateral leg swelling, haemoptysis, recent surgery or trauma, previous VTE and hormone use. It is only valid when the clinician's pretest probability is already under 15%.", "context": "In 2026 ED practice: gestalt first; if low risk and PERC negative, no test. Otherwise use Wells (or YEARS, van der Hulle Lancet 2017) to set D-dimer thresholds, with age-adjusted D-dimer (ADJUST-PE, JAMA 2014) or probability-adjusted D-dimer (YEARS or PEGeD), then CTPA if positive. NICE NG158 (2020) uses the two-level Wells score and allows PERC in low-suspicion patients. POCUS can support the diagnosis (right ventricular dilatation, proximal DVT) but not exclude it.", "pearls": ["Apply PERC only after you have judged the patient low risk; it is not a screening tool for everyone with chest pain.", "A Wells-unlikely patient with negative (age- or probability-adjusted) D-dimer needs no imaging.", "In pregnancy, adapted YEARS or the pregnancy-adapted algorithm reduces CT use.", "Hypoxia or tachycardia that you cannot explain should keep PE on the list even after a 'normal' chest film."], "pitfalls": ["Ordering a D-dimer on PERC-negative low-risk patients and then chasing the false positive.", "Applying PERC in high-prevalence settings or to inpatients, where it was not validated.", "Scoring 'alternative diagnosis less likely' as 3 points by default."], "hook": "PERC is the bouncer at the door who turns away the obviously innocent; Wells is the detective who decides how hard to search everyone else.", "sources": ["https://en.wikipedia.org/wiki/Wells_score_(pulmonary_embolism)", "https://mdcalc.scholasticahq.com/article/160870-updated-review-of-the-perc-rule", "https://www.wikijournalclub.org/wiki/PROPER"]}, "wells-dvt": {"hist": "Philip Wells and colleagues in Ottawa first published a clinical model for DVT in The Lancet in 1995 and refined it in a 1997 Lancet paper that combined pretest probability with ultrasound. In 2003 they published a modified version, adding previous DVT, in a randomised trial in the New England Journal of Medicine of 1,096 outpatients, showing that a 'DVT unlikely' score plus a negative D-dimer could safely avoid ultrasound.", "etym": "Thrombosis comes from the Greek thrombos, a clot or lump, with -osis, a condition. Deep refers to the deep venous system beneath the muscular fascia.", "culture": "The Wells scores are among the most cited clinical decision rules in medicine and helped move VTE diagnosis away from eponymous signs such as Homans' towards probability-based reasoning. The DVT score includes a minus 2 for 'alternative diagnosis at least as likely', which, like its PE cousin, builds clinical judgement directly into the arithmetic.", "anat": "The items map onto Virchow's triad and to the anatomy of venous drainage: active cancer, bedridden or recent major surgery, paralysis or plaster immobilisation (stasis and hypercoagulability), localised tenderness along the deep veins, entire leg swelling, calf swelling over 3 cm compared with the other side, pitting oedema in the symptomatic leg and collateral superficial (non-varicose) veins (obstruction to deep flow). Proximal DVT (popliteal and above) carries the main embolic risk, which is why ultrasound protocols focus on the femoral and popliteal veins.", "context": "In 2026 the two-level Wells score (likely 2 or more, unlikely 1 or less) is the standard in NICE NG158 (2020): likely means proximal leg ultrasound within 4 hours (or interim anticoagulation and D-dimer if delayed), unlikely means D-dimer first, then ultrasound if positive. Emergency physician POCUS with two- or three-point compression is accurate in trained hands. Age-adjusted D-dimer cut-offs are increasingly used to reduce unnecessary scans.", "pearls": ["Measure calf circumference 10 cm below the tibial tuberosity in both legs; a difference over 3 cm earns a point.", "Previous documented DVT earns a point in the modified score.", "A negative proximal ultrasound in a 'likely' patient with positive D-dimer needs a repeat scan in about 6 to 8 days.", "Consider the alternative: Baker cyst, cellulitis, haematoma, muscle tear; ultrasound can show these too."], "pitfalls": ["Using D-dimer alone to exclude DVT in a 'likely' patient.", "Not looking for an alternative diagnosis before scoring 'alternative at least as likely'.", "Forgetting that a normal-looking leg does not exclude DVT in a bedbound or cancer patient."], "hook": "Wells is a balance scale: Virchow's three weights on one side, an alternative diagnosis tipping it back by two.", "sources": ["https://www.2minutemedicine.com/the-wells-dvt-criteria-a-validated-clinical-prediction-model-for-the-detection-of-deep-vein-thrombosis-classics-series", "https://gpnotebook.com/pages/cardiovascular-medicine/clinical-probability-of-dvt", "https://en.wikipedia.org/wiki/Wells_score_(pulmonary_embolism)"]}, "rlq-tender": {"hist": "Charles Heber McBurney (1845 to 1913), a New York surgeon, described the point in 'Experience with early operative interference in cases of disease of the vermiform appendix' (New York Medical Journal, 1889; 50:676 to 684). He placed the seat of greatest pain 'very exactly between an inch and a half and two inches' from the anterior superior iliac spine along a line to the umbilicus, and argued for early operation. His muscle-splitting incision followed in 1894 and is a separate eponym.", "etym": "An eponym from McBurney; the modern definition (one third of the way from the ASIS to the umbilicus) is a later standardisation. Appendix is Latin for 'something hung on', from appendere; vermiform means worm-shaped, from vermis, worm.", "culture": "McBurney's work built on Reginald Heber Fitz of Boston, who coined the term appendicitis in 1886; by coincidence both men carried the middle name Heber. McBurney never gave the point a precise ratio, so the 'one third' rule familiar to every student is a later tidying-up of his inch-and-a-half to two-inch range.", "anat": "The point overlies the usual position of the base of the appendix where the taeniae coli converge on the caecum. Early appendicitis causes poorly localised periumbilical pain via visceral afferents (T10) because the appendix is a midgut structure; once inflammation reaches the overlying parietal peritoneum, which has somatic innervation, pain and tenderness localise to the right iliac fossa. The tip of the appendix is highly variable (retrocaecal, pelvic, subcaecal, pre- or post-ileal), so tenderness may be maximal elsewhere.", "context": "Right lower quadrant tenderness is the most consistent examination finding in appendicitis but is not diagnostic alone. In 2026 it feeds into scores such as Alvarado, the Appendicitis Inflammatory Response (AIR) score and the Adult Appendicitis Score, which stratify patients towards discharge with safety-netting, observation, ultrasound or CT. Ultrasound (including POCUS) is first-line in children and pregnancy; low-dose CT is common in adults; and non-operative antibiotic management is an option for selected uncomplicated cases.", "pearls": ["Start palpating far from the pain and approach McBurney's point last; watch the face, not your hand.", "Ask the patient to cough or hop, or jolt the bed: pain in the right iliac fossa suggests peritoneal irritation.", "Pelvic appendicitis may cause suprapubic or rectal tenderness with little at McBurney's point.", "Migration of pain from umbilicus to right iliac fossa is one of the most useful historical features."], "pitfalls": ["Excluding appendicitis because tenderness is not exactly at McBurney's point.", "Forgetting gynaecological causes (ectopic pregnancy, ovarian torsion) in women; always check a pregnancy test.", "Being falsely reassured in the elderly, immunosuppressed or pregnant, who may have minimal localised tenderness."], "hook": "Draw a line from hip bone to belly button and walk one third of the way: that is where the worm-shaped tail is pinned to the bowel.", "sources": ["https://litfl.com/appendicitis-eponyms/", "https://en.wikipedia.org/wiki/McBurney%27s_point"]}, "rovsing": {"hist": "Niels Thorkild Rovsing (1862 to 1927), a Danish surgeon in Copenhagen, published the sign in Zentralblatt für Chirurgie in 1907 (34:1257 to 1259), having developed it in 1904 and used it in more than 100 cases. His original manoeuvre was not simple pressure: he compressed the descending colon in the left iliac fossa and slid his hands upward towards the splenic flexure, intending to push gas back towards the caecum. Emil Perman, in Stockholm, had described right iliac fossa pain on pressure over the left abdomen in 1904.", "etym": "An eponym from Rovsing; the sign is sometimes called the Perman-Rovsing sign to acknowledge Perman's earlier description.", "culture": "What most clinicians call Rovsing's sign today (press on the left, pain on the right) is closer to Perman's 1904 observation than to Rovsing's own colonic gliding technique. Later manometry by Davey (1956) found no rise in caecal pressure unless the colon was already distended, undermining Rovsing's explanation, and reviews note that few studies have reproduced his original technique.", "anat": "Rovsing believed that pressure on the descending colon pushed gas retrogradely to the caecum, which cannot decompress into the ileum because of the ileocaecal valve, so the inflamed caecum and appendix were stretched. Alternative explanations include shifting of bowel loops and peritoneum against the inflamed parietal peritoneum in the right iliac fossa, or transmitted traction. Either way, a positive sign points to localised peritoneal irritation on the right.", "context": "Rovsing's sign is a supportive, modestly specific finding for appendicitis, with wide reported ranges of sensitivity (about 19 to 75%) and specificity (about 58 to 93%). In 2026 it contributes to the overall clinical picture and scores, while ultrasound or CT confirms the diagnosis. It is useful when a patient is guarding the right iliac fossa so heavily that direct palpation is difficult.", "pearls": ["Press deeply and steadily in the left iliac fossa and ask where it hurts; pain felt on the right is the positive.", "Try the original manoeuvre: compress and slide upwards along the descending colon.", "Combine with cough tenderness and percussion tenderness rather than relying on one sign."], "pitfalls": ["Treating a negative Rovsing sign as reassurance; it is insensitive.", "Accepting pain felt locally on the left as positive; the pain must be referred to the right."], "hook": "Squeeze the left end of a toothpaste tube and the right end bulges: pressure on the left, pain on the right.", "sources": ["https://litfl.com/rovsing-sign/", "https://litfl.com/appendicitis-eponyms/"]}, "psoas": {"hist": "The psoas test is attributed to Sir Vincent Zachary Cope (1881 to 1974), the English surgeon whose 'Early Diagnosis of the Acute Abdomen' (first published 1921) became a classic; he also described the obturator test in the British Journal of Surgery in 1919. In Russian-language literature a similar sign is attributed to Vasily Parmenovich Obraztsov and called the Obraztsova sign.", "etym": "Psoas is from the Greek psoa (plural psoai), the muscles of the loins. Iliopsoas joins it with iliacus, from ilium, the flank bone.", "culture": "Cope's book went through many editions and remains in print as 'Cope's Early Diagnosis of the Acute Abdomen'; its emphasis on careful history and examination before imaging is still quoted. The psoas sign illustrates a general lesson Cope taught: the position of an inflamed organ, not just its identity, decides where and how it hurts.", "anat": "The right iliopsoas runs retroperitoneally behind the caecum and appendix to insert on the lesser trochanter of the femur. A retrocaecal appendix often lies directly on the psoas fascia, so stretching the muscle (passive hip extension) or contracting it (active flexion against resistance) moves the inflamed tissue and causes pain. Patients may lie with the hip slightly flexed to relax the muscle. Psoas abscess, retroperitoneal haematoma, pyelonephritis and iliac vessel bleeding can produce the same sign.", "context": "A positive psoas sign has modest specificity (about 79 to 97%) and low sensitivity (about 13 to 42%) for appendicitis, so it can raise suspicion of a retrocaecal appendix but cannot exclude appendicitis. In 2026 it is useful to remember when an atypical presentation (flank pain, limp, mild RIF findings) might otherwise be labelled renal colic or musculoskeletal pain, prompting ultrasound or CT. In a febrile patient with hip-flexion deformity and back pain, think psoas abscess and image with CT or MRI.", "pearls": ["Do it with the patient on the left side: passively extend the right hip; pain in the right lower abdomen is positive.", "Alternatively, ask the supine patient to lift the straight right leg against your hand.", "A patient lying with the right hip flexed and refusing to straighten it is already telling you about psoas irritation.", "Pair it with the obturator test to localise a pelvic appendix."], "pitfalls": ["Confusing hip joint or back pain with abdominal pain on the manoeuvre.", "Ruling out appendicitis because the psoas sign is negative."], "hook": "The psoas is a rope running behind the caecum: pull the rope (extend the hip) and whatever is inflamed and lying on it gets dragged.", "sources": ["https://litfl.com/appendicitis-eponyms/", "https://en.wikipedia.org/wiki/Psoas_sign", "https://litfl.com/vincent-zachary-cope/"]}, "murphy": {"hist": "John Benjamin Murphy (1857 to 1916), a Chicago surgeon, described the sign in 1903 in The Medical News (vol. 82), calling it 'the most characteristic and constant sign of gall-bladder hypersensitiveness'. He examined the seated patient from behind, with fingers hooked under the right costal margin, and noted that inspiration 'suddenly ceases as though it had been shut off'. Bernhard Naunyn had described palpating the right upper quadrant during inspiration in 1896, and Berkeley Moynihan described the supine thumb-under-the-ribs version in 1905.", "etym": "An eponym from J. B. Murphy. Cholecystitis combines the Greek chole, bile, kystis, bladder, and -itis, inflammation.", "culture": "Murphy was a flamboyant and controversial figure, famous also for the 'Murphy button' for bowel anastomosis and for his work in appendicitis surgery. He claimed he had 'never found this sign absent in a calculous or infectious case of gall-bladder or duct disease', a confidence modern data do not support. The sign technique taught today, supine with the hand under the costal margin, is closer to Naunyn's and Moynihan's methods than to Murphy's own.", "anat": "On deep inspiration the diaphragm descends, pushing the liver and gallbladder fundus down towards the examiner's fingers placed beneath the right costal margin at the mid-clavicular line. If the gallbladder wall and the adjacent parietal peritoneum are inflamed, contact causes sharp pain and an abrupt halt to inspiration. The same manoeuvre on the left side should not cause pain, which helps confirm specificity.", "context": "In 2026 ED practice Murphy's sign is part of the assessment of right upper quadrant pain; reported sensitivity ranges widely (about 44 to 97%) with modest specificity, and it is much less sensitive in older patients (around 48% in one series). Ultrasound, including POCUS, is first-line and the sonographic Murphy sign (maximal tenderness under the probe directly over the gallbladder) combined with gallstones has good predictive value. The Tokyo Guidelines 2018 combine local signs (Murphy's sign, RUQ mass or tenderness), systemic inflammation and imaging to diagnose and grade acute cholecystitis.", "pearls": ["Hold your fingers still under the costal margin and let the patient's breath bring the gallbladder to you; do not dig.", "Compare with the left side to show the response is specific.", "A sonographic Murphy sign is more reliable than the bedside version, but less so if the patient has had analgesia.", "Elderly and diabetic patients can have gangrenous cholecystitis with a negative Murphy's sign."], "pitfalls": ["Withholding analgesia to preserve the sign; modern evidence supports early analgesia.", "Treating a negative Murphy's sign as excluding cholecystitis, especially in the elderly.", "Pressing so hard that you cause pain from the abdominal wall or liver regardless of breathing."], "hook": "The diaphragm is a lift bringing the gallbladder down to your waiting fingers; if the passenger is inflamed, the lift stops with a gasp.", "sources": ["https://litfl.com/murphys-sign/", "https://ebmconsult.com/articles/physical-exam-murphys-sign", "https://www.mja.com.au/journal/2017/206/3/murphys-sign"]}, "cullen": {"hist": "Thomas Stephen Cullen (1869 to 1953), a Johns Hopkins gynaecologist, described bluish-black periumbilical discolouration in a 38-year-old woman with a ruptured ectopic pregnancy and no history of injury, presenting it to the American Gynecological Society in May 1918. George Grey Turner (1877 to 1951), a Newcastle surgeon, published 'Local discoloration of the abdominal wall as a sign of acute pancreatitis' in the British Journal of Surgery in 1920, describing two cases, one with flank (loin) discolouration.", "etym": "Both are eponyms. Ecchymosis, the general term for this bruising, is Greek ekchymosis, from ek, out, and chymos, juice, meaning juices pouring out. Grey Turner is often mistaken for a double-barrelled surname; his name was George Grey Turner.", "culture": "Although Cullen described his sign in ectopic pregnancy, most of the literature now links it to severe pancreatitis, where it appears in only about 1 to 3% of cases. Grey Turner himself was a pioneering surgeon who performed one of the first successful transhiatal oesophagectomies in 1933 and predicted that cancer would one day be treated by injection rather than surgery.", "anat": "Blood or pancreatic exudate tracks through tissue planes. In pancreatitis, enzymes and haemorrhagic fluid leak into the anterior pararenal space and track to the flank (Grey Turner) along the posterior abdominal wall; fluid can also track via the falciform and round ligaments of the liver to the umbilicus (Cullen). Because the tracking takes time, discolouration typically appears 24 to 72 hours or more after onset, often 3 to 5 days. Causes include haemorrhagic pancreatitis, ruptured ectopic, ruptured AAA, retroperitoneal haemorrhage on anticoagulants, and rectus sheath haematoma.", "context": "These are uncommon, late signs that indicate severe retroperitoneal or intraperitoneal haemorrhage; Grey Turner's sign occurs in about 3 to 5% of acute pancreatitis and is associated with a mortality of around 30 to 40%. In 2026 they should trigger immediate resuscitation and imaging: pregnancy test and POCUS for free fluid in women of reproductive age, aortic POCUS in older patients, and contrast CT for pancreatitis severity and retroperitoneal bleeding. Severity is graded by the revised Atlanta classification and clinical scores, not by the bruise.", "pearls": ["Always check a pregnancy test and do a FAST or pelvic scan in a woman with periumbilical bruising.", "In an elderly patient with flank bruising and back pain, think ruptured AAA.", "Ask about anticoagulants and recent procedures (femoral access, abdominal injections).", "Absence of these signs never excludes severe pancreatitis or haemorrhage."], "pitfalls": ["Mistaking them for trauma bruising and missing the underlying cause.", "Expecting them early; they are late signs, so their absence on arrival means little."], "hook": "Cullen is the belly button and Grey Turner turns the flank grey: blood seeping out to the surface like ink spreading through blotting paper.", "sources": ["https://litfl.com/atraumatic-abdominal-ecchymosis/", "https://litfl.com/cullen-sign/", "https://litfl.com/george-grey-turner/"]}, "carnett": {"hist": "John Berton Carnett, an American surgeon, described the test in 1926 in 'Intercostal neuralgia as a cause of abdominal pain and tenderness' (Surgery, Gynecology and Obstetrics 42:625 to 632). He believed much lower abdominal pain arose from the lower six thoracic nerves in the abdominal wall and wanted a simple way to distinguish this from visceral disease. Edgar Cyriax had earlier, in 1919, given a clear description of abdominal wall pain arising from structures other than the viscera.", "etym": "An eponym from J. B. Carnett. Neuralgia combines the Greek neuron, nerve, and algos, pain.", "culture": "Carnett's sign is a classic example of a cheap, quick test that can save patients from repeated imaging and endoscopy for chronic 'mystery' abdominal pain, much of which is anterior cutaneous nerve entrapment syndrome (ACNES). It has also been used, and sometimes misused, as a test for 'functional' or psychogenic pain, which risks dismissing real abdominal wall pathology.", "anat": "When the patient tenses the rectus muscles (head and shoulders lift or straight-leg raise), the contracted muscle shields the viscera from the examining hand, so visceral tenderness usually decreases. Pain arising in the abdominal wall itself, such as entrapment of the anterior cutaneous branches of T7 to T12 intercostal nerves where they pierce the rectus sheath, rectus sheath haematoma, hernia or myofascial pain, stays the same or worsens. A positive Carnett's sign (pain unchanged or worse) therefore points to the wall rather than the abdomen.", "context": "Carnett's test is most useful for chronic or recurrent localised abdominal pain, especially a fingertip-sized tender spot at the lateral rectus border, where it supports ACNES, which can be confirmed by local anaesthetic injection. In the acute ED setting its value is limited: a 2020 study found it unsuitable for distinguishing acute intra-abdominal pathology, and peritonitis can also hurt more on tensing. In 2026 it helps avoid unnecessary CT in returning patients, but red flags still require imaging.", "pearls": ["Find the point of maximal tenderness first with one fingertip, then ask the patient to lift head and shoulders while you keep pressing.", "ACNES usually has a small, precise tender spot along the lateral border of rectus with altered skin sensation around it.", "A rectus sheath haematoma, often in anticoagulated patients after coughing, gives a positive sign and a tender mass that does not cross the midline."], "pitfalls": ["Labelling a positive sign as 'functional' or psychological pain.", "Relying on it in acute, severe pain with fever or peritonism, where intra-abdominal disease must be excluded."], "hook": "Tense the abdominal wall like raising a shield: pain behind the shield fades, pain in the shield itself gets louder.", "sources": ["https://en.wikipedia.org/wiki/Carnett%27s_sign", "https://link.springer.com/article/10.1007/s11916-024-01223-9", "https://www.physio-pedia.com/Carnett_sign"]}, "aaa-palp": {"hist": "Abdominal aortic aneurysms have been described since antiquity, but the modern bedside evidence comes from Lederle and Simel's 1999 JAMA Rational Clinical Examination review 'Does this patient have abdominal aortic aneurysm?'. They showed that palpation sensitivity rises with aneurysm size, from about 29% for 3.0 to 3.9 cm aneurysms to about 76% for those 5 cm or more, and is reduced by abdominal girth.", "etym": "Aneurysm is from the Greek aneurysma, a widening, from ana-, up or throughout, and eurys, wide. Aorta is from the Greek aorte, from aeirein, to lift.", "culture": "In December 1948 the surgeon Rudolph Nissen found a large abdominal aortic aneurysm in Albert Einstein during abdominal surgery and wrapped it in cellophane to provoke fibrosis. The aneurysm ruptured in April 1955; Einstein declined further surgery and died on 18 April 1955 at Princeton Hospital.", "anat": "The abdominal aorta lies retroperitoneally to the left of the midline, bifurcating at about the level of L4, which corresponds roughly to the umbilicus. Normal diameter is about 2 cm; an aneurysm is 3 cm or more. Palpation assesses width, not pulse strength: an expansile pulsation pushes both examining fingers apart, whereas a transmitted pulsation from a mass lying on the aorta moves them in the same direction.", "context": "Palpation is a quick, safe screen but cannot exclude AAA, especially in obese patients or for smaller aneurysms. In 2026 ED practice, POCUS of the aorta is the bedside standard, with high sensitivity for AAA, though it does not reliably detect rupture, which needs CT in a stable patient. Population screening (for example the NHS programme inviting men at 65 and US screening of men 65 to 75 who have ever smoked) uses ultrasound. The classic triad of rupture (pain, hypotension, pulsatile mass) is often incomplete, and AAA is frequently misdiagnosed as renal colic.", "pearls": ["Lie the patient flat with knees bent; place both hands either side of the aorta just above and left of the umbilicus.", "Judge the width between your fingers, not how strongly the pulse hits them; over 2.5 cm warrants imaging.", "Thin patients often have a normal aorta that feels prominent; ultrasound settles it in a minute.", "Older smoker with 'renal colic', back pain or syncope: scan the aorta before anything else."], "pitfalls": ["Being reassured by an impalpable aorta in an obese patient.", "Assuming palpation can rupture an aneurysm; gentle examination is safe and recommended.", "Diagnosing renal colic in a patient over 50 without excluding AAA."], "hook": "Your two index fingers are calipers on a garden hose: a normal hose pulses under them, an aneurysm pushes them apart.", "sources": ["https://www.aafp.org/pubs/afp/issues/1999/0415/p2343a.html", "https://mdedge.com/content/einsteins-aneurysm-cellophane-and-rudolph-nissen"]}, "purpura-glass": {"hist": "The glass (tumbler) test, in which a clear drinking glass is pressed against a rash to see whether it fades, has been promoted widely to parents, notably by UK organisations such as the Meningitis Research Foundation and the former Public Health Laboratory Service. Its exact origin and first use are not documented in the literature. A Best Evidence Topic review (searching to 2003) found no studies evaluating its sensitivity or specificity.", "etym": "Purpura is Latin for purple, from the Greek porphyra, the purple dye from murex shellfish. Petechia comes from the Italian petecchia, a small spot; meningococcus from Greek meninx, membrane, and kokkos, berry.", "culture": "Thompson and colleagues (Lancet, 2006) found that in children with meningococcal disease, the haemorrhagic rash was a late feature (classic features at a median of 13 to 22 hours), while leg pain, cold hands and feet and abnormal skin colour appeared earlier, at a median of about 7 to 12 hours. Charities now emphasise 'do not wait for a rash', as heavy reliance on the glass test can falsely reassure parents.", "anat": "A blanching rash (such as viral erythema) is due to dilated capillaries; pressure empties them and the colour fades. Petechiae and purpura are red cells that have leaked out of vessels into the dermis, so pressure cannot push them away and the rash remains visible through the glass. In meningococcal sepsis, endotoxin-driven endothelial damage, microvascular thrombosis and disseminated intravascular coagulation cause leakage and, in severe cases, purpura fulminans.", "context": "In 2026, a non-blanching rash with fever or illness is treated as meningococcal disease until proven otherwise; NICE NG240 (2024) notes that purpura over 2 mm and a rapidly spreading rash increase likelihood, but that not everyone with meningococcal disease has a rash. Give parenteral antibiotics promptly (prehospital if meningococcal disease is suspected) and assess with sepsis tools. Other causes of non-blanching rash include ITP, Henoch-Schönlein purpura (IgA vasculitis), leukaemia, coughing or vomiting (petechiae above the nipple line) and non-accidental injury.", "pearls": ["Press firmly with the side of a clear glass; spots still visible through it do not blanch.", "On dark skin check paler areas: palms, soles, conjunctivae and the roof of the mouth.", "Petechiae confined to the superior vena cava distribution after vomiting or coughing in a well child are often benign, but only if the child is truly well.", "Mark the edge of the rash with a pen and recheck: spreading purpura means deterioration."], "pitfalls": ["Waiting for a rash before suspecting meningococcal disease.", "Being reassured by a blanching rash in an unwell child; early meningococcal rashes can blanch.", "Missing petechiae in dark skin by not looking at mucous membranes and palms."], "hook": "Leaked ink stays put: you can push blood back through a pipe, but not blood that has already spilled out onto the carpet.", "sources": ["https://bestbets.org/bets/bet.php?id=616", "https://meningitisnow.org/meningitis-explained/signs-and-symptoms/glass-test", "https://blogs.the-hospitalist.org/content/value-early-meningococcal-symptoms-debated", "https://www.nice.org.uk/guidance/NG240/chapter/rationale-and-impact"]}, "qsofa": {"hist": "The quick Sequential Organ Failure Assessment (qSOFA) was introduced in 2016 alongside the Sepsis-3 definitions (Singer and colleagues, JAMA), with its derivation and validation by Seymour and colleagues in the same issue. It gives one point each for respiratory rate 22 or more, altered mentation and systolic blood pressure 100 mmHg or less; a score of 2 or more identified infected patients at higher risk of death. NEWS2 was published by the Royal College of Physicians of London in 2017 as an updated National Early Warning Score.", "etym": "Sepsis is from the Greek sepsis, putrefaction or decay, a term used in the Hippocratic writings. qSOFA is a contraction of 'quick SOFA'; SOFA was originally the Sepsis-related Organ Failure Assessment, later Sequential Organ Failure Assessment.", "culture": "qSOFA was designed as a prognostic prompt, not a screening test, but was widely adopted for screening, where its low sensitivity missed many septic patients. The Surviving Sepsis Campaign 2021 guidelines strongly recommended against using qSOFA as a single screening tool compared with SIRS, NEWS or MEWS.", "anat": "Each item reflects early organ dysfunction from a dysregulated host response: tachypnoea from metabolic acidosis, lung injury and cytokine-driven respiratory drive; altered mentation from septic encephalopathy and hypoperfusion; and hypotension from vasodilatation, capillary leak and myocardial depression. NEWS2 adds oxygen saturation (with a separate scale for hypercapnic respiratory failure), supplemental oxygen, heart rate, temperature and new confusion, giving a more graded and sensitive picture of deterioration.", "context": "In 2026 adult ED sepsis screening relies on early warning scores such as NEWS2 (in the UK, NICE sepsis guidance updated in 2024 uses NEWS2: 7 or more high risk, 5 to 6 moderate, any single parameter scoring 3 triggers urgent review) plus clinical judgement, lactate and source identification. qSOFA remains a quick prognostic indicator in infected patients, but a negative score must not delay antibiotics. Children use separate criteria, including the 2024 Phoenix sepsis criteria for paediatric sepsis.", "pearls": ["Count the respiratory rate for a full minute; it is the most neglected and most predictive vital sign.", "Any new confusion (GCS under 15) in an infected patient is organ dysfunction until proven otherwise.", "A qSOFA of 0 or 1 does not exclude sepsis; use NEWS2, lactate and clinical gestalt.", "Recalculate scores after interventions; deterioration matters more than a single value."], "pitfalls": ["Using qSOFA as a rule-out screening tool.", "Delaying antibiotics in a sick patient until a score threshold is met.", "Forgetting that NEWS2 can be falsely low in patients on beta-blockers, in the elderly, or with chronic hypoxia on the wrong SpO2 scale."], "hook": "qSOFA asks three quick questions at the door: breathing fast, thinking slow, pressure low; NEWS2 is the full interview.", "sources": ["https://sccm.org/sepsisguidelines", "https://www.nice.org.uk/guidance/ng253/chapter/Evaluating-risk", "https://pubmed.ncbi.nlm.nih.gov/26903338/"]}, "gcs": {"hist": "Graham Teasdale and Bryan Jennett, neurosurgeons at the University of Glasgow (Institute of Neurological Sciences), published 'Assessment of coma and impaired consciousness: a practical scale' in The Lancet in 1974. They wanted to replace vague, inconsistent bedside descriptions of conscious level with three separately recorded responses: eye opening, verbal response and motor response. The original motor scale did not separate normal flexion withdrawal from abnormal (decorticate) flexion, so the maximum was 14; abnormal flexion was added shortly afterwards, giving the 3 to 15 range used today. In 2018 the same group published the GCS-Pupils score (GCS-P) in the Journal of Neurosurgery, subtracting points for unreactive pupils.", "etym": "Named after the city where it was devised rather than a person; 'coma' comes from the Greek koma, deep sleep.", "culture": "The authors presented the scale as three separate observations, and numbers were attached partly so that research data could be fed into early computers; the single summed score became popular later and, as the Glasgow group itself notes, loses detail and discrimination. A GCS of 10 made of E4 V1 M5 (an aphasic but alert patient) and one made of E1 V4 M5 are very different patients, which is why the official guidance is to report the components.", "anat": "Wakefulness depends on the ascending reticular activating system in the upper brainstem tegmentum projecting via the thalamus to both hemispheres, so coma needs either brainstem/diencephalic damage or diffuse bilateral cortical dysfunction. Eye opening tests arousal, verbal response tests the integrity of higher cortical networks, and the motor response maps descending pathways: localising needs cortical processing, abnormal flexion classically reflects lesions above the midbrain with rubrospinal pathways preserved, and extension reflects deeper brainstem involvement. The motor score carries most of the prognostic weight in trauma because it is the most graded and least confounded by intubation or facial injury.", "context": "GCS remains the universal language for conscious level in trauma, ATLS, NICE NG232 head-injury pathways, CT head rules and triage, and a falling GCS is still one of the most important bedside triggers for repeat imaging or neurosurgical referral. It is less discriminating in the mildly impaired (GCS 13 to 15), where amnesia and confusion matter more, and in non-traumatic coma the FOUR score is an alternative that adds brainstem reflexes and respiration. 'GCS 8, intubate' is a rule of thumb, not a guideline; airway protection is decided on the actual airway, trajectory and the clinical situation.", "pearls": ["Report it as E, V and M with the total, for example E2 V2 M5 = 9, and record the best motor response from the better side.", "Use a standard stimulus: trapezius pinch or supraorbital pressure for localising, fingertip pressure for flexion; sternal rub leaves bruises and is not recommended by the Glasgow group.", "Localising means the hand crosses the midline or rises above the clavicle towards the stimulus; withdrawal is rapid and away; abnormal flexion is slow, stereotyped and with wrist flexion and thumb tucked.", "Record 'NT' (not testable) for intubation, eye swelling or language barriers rather than guessing a 1.", "A drop of 2 or more points, or of 1 in the motor score, is a change in the patient, not in the observer: act on it."], "pitfalls": ["Quoting only a total, which hides the motor score that predicts outcome and drives decisions.", "Scoring before correcting confounders such as hypoglycaemia, hypoxia, hypotension, sedatives, alcohol or post-ictal state, then using that number to label a 'severe brain injury'.", "Confusing spinal reflex withdrawal or abnormal flexion with localising, which inflates the motor score."], "hook": "Glasgow speaks in three voices, Eyes, Voice and Motor, and the Motor voice is the one that tells you the future, so never let it be drowned in a single summed number.", "sources": ["https://glasgowcomascale.org/what-is-gcs/", "https://neuronewsinternational.com/looking-back-on-40-years-of-the-glasgow-coma-scale", "https://www.hmpgloballearningnetwork.com/site/emsworld/article/10318723/ems-recap-glasgow-coma-scale"]}, "babinski": {"hist": "Joseph Babinski (1857 to 1932), a Paris neurologist of Polish émigré parents and a pupil of Charcot, presented 'Sur le réflexe cutané plantaire dans certaines affections organiques du système nerveux central' to the Société de Biologie in 1896, reporting that in organic central nervous system disease the toes, instead of flexing, extend on stroking the sole. In 1903, in the Revue Neurologique ('De l'abduction des orteils'), he added fanning of the toes as a further sign of pyramidal disease. His particular aim was to distinguish organic from hysterical paralysis, a pressing question in Charcot's Salpêtrière.", "etym": "An eponym from the Polish surname Babiński; 'plantar' is from the Latin planta, the sole of the foot, and 'pyramidal' refers to the pyramid-shaped bulges of the corticospinal tracts on the ventral medulla.", "culture": "Babinski failed the 1892 agrégation examination, a setback widely attributed to academic rivalry with Charcot's school, so he never held a university chair and spent his career as a hospital physician at La Pitié; biographers have called him 'Babinski the great: failure did not deter him'. Freud described him as Charcot's preferred pupil.", "anat": "Toe extension is not a new reflex but part of the primitive flexion withdrawal (shortening) synergy, in which extensor hallucis longus, tibialis anterior and the hip and knee flexors contract together to pull the foot away. In infants, and after damage to the corticospinal tract at any level from cortex to cord, this synergy is released, so the big toe joins the withdrawal instead of being recruited into the mature downward toe flexion. The corticospinal tract myelinates over the first year or two of life, which is why an upgoing toe is normal in infants.", "context": "In 2026 the Babinski sign is still a fast, cheap marker of an upper motor neurone lesion in the ED: in suspected stroke, cord compression, post-ictal states and coma it helps localise and lateralise before imaging. It does not stand alone; it is integrated into NIHSS-style examination and confirmed by CT, CT angiography or MRI. Its interobserver reliability is modest, so a single equivocal toe should never outweigh the rest of the neurological examination.", "pearls": ["Use a blunt object (key or orange stick) along the lateral sole from heel towards the little toe, then curve medially across the metatarsal heads; the first movement of the big toe is the answer.", "A true extensor response is slow and sustained extension of the hallux at the metatarsophalangeal joint, often with hip and knee flexion and contraction of tibialis anterior.", "If the patient withdraws briskly, try Chaddock (stroking below the lateral malleolus) or Oppenheim (pressing down the shin); they test the same reflex with less ticklishness.", "In acute cord or massive cerebral injury the plantar may be mute (spinal shock) before becoming extensor; absence of a response is information, not normality.", "Bilateral upgoing toes in a comatose patient may be metabolic (hypoglycaemia, post-ictal, drugs), so check glucose before assuming bilateral structural damage."], "pitfalls": ["Stroking too hard or too medially, provoking voluntary withdrawal or a grasp reflex that looks like extension.", "Calling it 'positive' or 'negative' in the notes; write 'flexor', 'extensor' or 'equivocal' for each side.", "Interpreting an upgoing toe as abnormal in an infant under about one year."], "hook": "When the pyramidal tract falls silent the foot remembers being a baby, and the big toe climbs back up the withdrawal ladder.", "sources": ["https://litfl.com/joseph-babinski/", "https://www.academie-medecine.fr/luvre-de-babinski/"]}, "kernig": {"hist": "Vladimir (Woldemar) Kernig (1840 to 1917), a physician at the Obukhov Hospital in St Petersburg, described his sign in 1882 in the St Petersburger Medicinische Wochenschrift ('Über ein Krankheitssymptom der acuten Meningitis'): in meningitis, patients seated with hips and knees flexed could not extend the knee beyond about 135 degrees without pain. Józef Brudziński (1874 to 1917), a Polish paediatrician, described a contralateral leg reflex in 1908 and, in 1909, his best-known 'neck sign' in children with meningitis, in which passive neck flexion produces reflex flexion of the hips and knees; he later added cheek and symphyseal signs (1916).", "etym": "'Meningitis' comes from the Greek meninx, membrane, plus -itis, inflammation; both signs are eponyms after the physicians who described them.", "culture": "In the best-known adult validation, Thomas and colleagues (Clinical Infectious Diseases, 2002) found Kernig's and Brudzinski's signs each had a sensitivity of only about 5% for meningitis, so the classic textbook signs are almost useless for ruling it out. Brudziński was also a national figure: he founded the Polish paediatric journal Przegląd Pediatryczny and was elected rector of the re-established University of Warsaw in 1915, dying aged 43.", "anat": "Inflamed meninges and nerve roots are pain-sensitive to stretch. Extending the knee with the hip flexed (Kernig) tensions the sciatic nerve and lumbosacral roots within their inflamed dural sleeves; flexing the neck (Brudzinski) pulls the spinal cord and dura cranially, and the patient reflexly flexes hips and knees to slacken the roots. Both are protective spasm responses to root traction, which is why they appear late and mainly in severe or advanced inflammation.", "context": "In 2026 these signs are documented but do not change the pathway: if meningitis is suspected, take blood cultures and give antibiotics (and dexamethasone where indicated) without waiting, and proceed to lumbar puncture when safe. Their specificity is respectable, so a clearly positive sign raises suspicion, but a negative examination must never stop a lumbar puncture or treatment. Fever, headache, altered mental state, rash and clinical gestalt drive the decision far more than meningeal signs.", "pearls": ["Perform Kernig supine: flex hip and knee to 90 degrees, then extend the knee; resistance or pain in the back or hamstrings is positive, and look at both sides.", "For Brudzinski, keep a hand on the chest and flex the neck; watch the hips and knees, not the face.", "These signs are most useful in children and in severe disease; in the elderly, the very young infant and the immunosuppressed they are often absent.", "Unilateral Kernig is more likely a sciatica or root lesion than meningitis.", "Old age, cervical spondylosis and Parkinsonism produce neck stiffness without meningitis; correlate with the whole picture."], "pitfalls": ["Using a negative Kernig or Brudzinski to talk yourself out of a lumbar puncture or antibiotics.", "Delaying antibiotics to perform or repeat meningeal sign examinations.", "Confusing hamstring tightness or lumbar disc disease with a positive Kernig."], "hook": "Kernig and Brudzinski are the old sentries who shout only when the enemy is already inside the walls, so never wait for them before you fire the antibiotics.", "sources": ["https://en.wikipedia.org/wiki/Woldemar_Kernig", "https://wl.uwm.edu.pl/kpat/badania-naukowe/pioneers-neuroscience-poland/jozef-brudzinski", "https://canadiem.org/boring-question-useful-physical-examination-manoeuvres-patient-suspected-meningitis-adults/", "https://academic.oup.com/cid/article/35/1/46/281915"]}, "neck-stiffness": {"hist": "Nuchal rigidity has been a cornerstone of the clinical description of meningitis since the 19th century, alongside the signs of Kernig and Brudziński. Jolt accentuation of headache was described by Toshiki Uchihara and Hiroshi Tsukagoshi in 1991 in the journal Headache ('Jolt accentuation of headache: the most sensitive sign of CSF pleocytosis'), reporting a sensitivity of about 97% and specificity of 60% for CSF pleocytosis in a small series of 54 patients.", "etym": "'Nuchal' comes from the medieval Latin nucha, the nape of the neck (itself from the Arabic nukha, spinal marrow); 'jolt' is plain English for a sudden shake.", "culture": "The jolt test was briefly hailed as the sign that could rule meningitis out, but later emergency department studies, including Nakao and colleagues in the American Journal of Emergency Medicine (2014, 'poor predictors of meningitis in adults'), found far lower sensitivity, so a negative jolt test no longer licenses skipping a lumbar puncture. Thomas and colleagues (2002) found nuchal rigidity had a sensitivity of only around 30% in adults with suspected meningitis.", "anat": "True meningeal neck stiffness is resistance to passive flexion only (chin to chest), because flexion stretches the inflamed posterior meninges and roots, while rotation and extension remain relatively free. Rigidity to movement in all directions suggests cervical spondylosis, Parkinsonian rigidity or muscle spasm. Jolt accentuation works because rapid horizontal head rotation, two to three times per second, produces sudden pressure and traction changes in sensitised meninges and intracranial pain-sensitive structures, amplifying an existing headache.", "context": "Both tests are quick add-ons in the febrile headache patient in the ED, but in 2026 their role is supportive, not decisive: suspicion of meningitis or subarachnoid haemorrhage is acted on with cultures, empirical antibiotics, CT where indicated, and lumbar puncture. Neck stiffness is also a classic feature of subarachnoid haemorrhage, which the Ottawa SAH rule includes. A positive finding raises the stakes; a negative finding changes little.", "pearls": ["Test passive flexion gently with the patient supine and relaxed; then check rotation, because meningism spares rotation.", "For jolt, ask the patient to turn the head horizontally two to three times per second; worsening of the existing headache is positive.", "Jolt only makes sense if the patient already has a headache.", "In the drowsy or comatose patient meningism may be lost; its absence there means nothing.", "Neck stiffness in a febrile child or older adult is non-specific; pneumonia, pharyngitis and retropharyngeal abscess can mimic it."], "pitfalls": ["Using a negative jolt test as a rule-out, as early enthusiasm suggested.", "Testing in a patient with possible cervical spine injury.", "Labelling generalised neck rigidity from spondylosis or Parkinsonism as meningism."], "hook": "Shake the head and the angry meninges shout: but silence from them is never a promise.", "sources": ["https://www.wikem.org/wiki/Jolt_test", "https://canadiem.org/boring-question-useful-physical-examination-manoeuvres-patient-suspected-meningitis-adults/", "https://cochranelibrary.com/cdsr/doi/10.1002/14651858.CD012824"]}, "hints": {"hist": "The HINTS examination was published by Jorge Kattah, David Newman-Toker and colleagues in Stroke in 2009 ('HINTS to diagnose stroke in the acute vestibular syndrome: three-step bedside oculomotor examination more sensitive than early MRI diffusion-weighted imaging'). In 101 high-risk patients it was 100% sensitive and 96% specific for stroke, whereas early MRI missed eight strokes later shown on repeat imaging. The first component, the head impulse test, had been described by Michael Halmagyi and Ian Curthoys in Archives of Neurology in 1988 ('A clinical sign of canal paresis').", "etym": "HINTS stands for Head Impulse, Nystagmus, Test of Skew; the authors coined the companion mnemonic INFARCT (Impulse Normal, Fast-phase Alternating, Refixation on Cover Test) for the dangerous pattern.", "culture": "HINTS is a paradox: the one reassuring finding is an abnormal head impulse test, which confuses many learners. When used by emergency clinicians without specific training its accuracy falls sharply, and the 2023 GRACE-3 guideline states that it should be used only by trained clinicians and only in patients with nystagmus.", "anat": "The head impulse test probes the vestibulo-ocular reflex, a three-neuron arc from the horizontal semicircular canal through the vestibular nuclei to the abducens and oculomotor nuclei; in vestibular neuritis the arc is broken peripherally, so the eyes are dragged off target and a corrective saccade follows, whereas most cerebellar and brainstem strokes spare the arc and the reflex looks normal. Peripheral nystagmus is unidirectional because one labyrinth is persistently underactive, while gaze-evoked direction-changing nystagmus reflects failure of the brainstem-cerebellar neural integrator. Skew deviation is vertical misalignment from imbalance in otolith-ocular (graviceptive) pathways, a central sign.", "context": "HINTS applies only to the acute vestibular syndrome: continuous vertigo or dizziness for hours to days with nystagmus, nausea and gait instability. GRACE-3 (SAEM, 2023) recommends trained clinicians use HINTS, supported by a hearing test (HINTS plus) and gait assessment, advises against CT for this purpose, and reserves MRI as a confirmatory test for central or equivocal findings. Early MRI DWI can miss small posterior circulation strokes in the first 24 to 48 hours, so a dangerous HINTS pattern overrides a normal early scan.", "pearls": ["Only perform HINTS in a patient who is dizzy right now and has spontaneous nystagmus; it is meaningless in the patient who is well between episodes.", "For the head impulse, hold the head, ask the patient to fix on your nose, and make small, fast, unpredictable turns of 10 to 20 degrees; look for a catch-up saccade back to your nose.", "Any one dangerous component (normal impulse, direction-changing nystagmus, skew) means central until proven otherwise.", "Add a finger-rub hearing test: new unilateral hearing loss suggests AICA infarction, which can produce a falsely 'peripheral' head impulse.", "Always walk the patient: inability to stand or walk unaided is a strong central flag, especially if there is no nystagmus."], "pitfalls": ["Applying HINTS to episodic or positional vertigo, where it does not apply and a normal head impulse will wrongly suggest stroke.", "Reading the head impulse in reverse: an abnormal (positive) impulse is the reassuring, peripheral finding.", "Trusting a normal CT or early MRI over a dangerous HINTS examination."], "hook": "If the eyes stay locked on your nose when you whip the head, the ear is fine and the brain may be the problem: a perfect reflex is the scary one.", "sources": ["https://www.wikijournalclub.org/wiki/HINTS_study", "https://read.qxmd.com/read/3390028/a-clinical-sign-of-canal-paresis", "https://www.guidelinecentral.com/guideline/2775908/"]}, "dix-hallpike": {"hist": "Margaret Dix (1911 to 1991) and Charles Hallpike (1900 to 1979), working at the National Hospital for Nervous Diseases, Queen Square, London, where Hallpike directed the Medical Research Council's otological research unit, described the manoeuvre in 1952. Their paper, 'The pathology, symptomatology and diagnosis of certain common disorders of the vestibular system', appeared in both the Proceedings of the Royal Society of Medicine and the Annals of Otology, Rhinology and Laryngology, and defined the clinical features of benign paroxysmal positional vertigo. Robert Bárány had described positional vertigo with nystagmus in 1921.", "etym": "Named after its two authors; 'vertigo' is Latin for a whirling or turning, from vertere, to turn, and 'nystagmus' is from the Greek nystagmos, nodding or drowsiness.", "culture": "The test is often shortened to 'the Hallpike', quietly dropping Margaret Dix, his long-standing co-author and an accomplished otologist in her own right. The original paper called it a positional ('Lagerungs') test, reflecting the German vestibular tradition.", "anat": "Turning the head 45 degrees to one side aligns that side's posterior semicircular canal with the sagittal plane; lying back with the head extended then brings the canal into a vertical, gravity-dependent position. In canalithiasis, free otoconial debris dislodged from the utricle falls within the canal and drags endolymph, deflecting the cupula. This produces, after a short latency, torsional upbeating nystagmus with the upper pole of the eye beating towards the lower ear, which fatigues within about a minute.", "context": "The Dix-Hallpike remains the reference bedside test for posterior canal BPPV, the commonest cause of triggered episodic vertigo, and GRACE-3 (2023) and the AAO-HNS BPPV guideline both recommend it, with no routine CT or MRI when findings are typical. Horizontal canal BPPV is tested with the supine roll test instead. A typical positive test should lead straight to a repositioning manoeuvre in the ED.", "pearls": ["Explain first, then move briskly: sit the patient so the head will hang about 20 degrees below horizontal, turn 45 degrees, and lie back within one to two seconds.", "Watch the eyes for at least 30 seconds; the typical response has a latency of a few seconds, is torsional-upbeating, crescendo-decrescendo, and lasts under a minute.", "The side that provokes the nystagmus (lower ear) is the affected side; test both sides.", "Nystagmus reverses direction on sitting up, a useful confirmation.", "Pure downbeat or non-fatiguing positional nystagmus, or nystagmus without vertigo, is a central warning sign and needs imaging."], "pitfalls": ["Performing the test in a patient with continuous vertigo and spontaneous nystagmus (acute vestibular syndrome), where it is unhelpful and misleading.", "Not waiting long enough for the latency, or letting the patient close the eyes.", "Ignoring neck or back contraindications; use a side-lying alternative when extension is unsafe."], "hook": "Tip the ear down and let the stones tumble: a short wait, a twisting upbeat, then quiet, is the signature of loose crystals in the back canal.", "sources": ["https://litfl.com/charles-skinner-hallpike/", "https://www.guidelinecentral.com/guideline/2775908/"]}, "epley": {"hist": "John Epley (1930 to 2019), an otolaryngologist in private practice in Portland, Oregon, presented his canalithiasis theory and the first version of the manoeuvre in 1980. He published 'The canalith repositioning procedure: for treatment of benign paroxysmal positional vertigo' in Otolaryngology, Head and Neck Surgery in 1992. His original procedure included sedation and mastoid vibration, both of which the modified Epley used today omits.", "etym": "An eponym after John Epley; 'canalith' combines the Latin canalis, channel, with the Greek lithos, stone, describing otoconial debris loose in a semicircular canal.", "culture": "Epley faced more than a decade of scepticism and ridicule from colleagues, and in 1996 the Oregon Board of Medical Examiners investigated him for alleged unprofessional conduct, a case dismissed in 2001. The manoeuvre he was mocked for is now first-line treatment in international guidelines.", "anat": "The manoeuvre uses gravity to roll free otoconia through the posterior semicircular canal and out of its common crus back into the utricle, where they no longer deflect the cupula. Each position is held until the induced nystagmus and vertigo settle, which signals that the debris has stopped moving. It treats canalithiasis of the posterior canal; horizontal canal and cupulolithiasis variants need different manoeuvres.", "context": "For posterior canal BPPV confirmed by a typical Dix-Hallpike, GRACE-3 (2023) and the AAO-HNS guideline recommend the Epley manoeuvre as treatment, and most patients are cured within one to a few cycles. Routine vestibular suppressants are not recommended and post-manoeuvre posture restrictions are unnecessary. The Semont (liberatory) manoeuvre is an effective alternative, and patients can be taught self-treatment at home.", "pearls": ["Start from the positive Dix-Hallpike position, then turn the head 90 degrees to the other side, roll onto that shoulder with the face down, and sit up, holding each position about 30 to 60 seconds.", "Nystagmus in the same direction during the third position predicts success; reversed nystagmus suggests the debris has gone the wrong way.", "Repeat the Dix-Hallpike after the manoeuvre; repeat the Epley if still positive.", "Warn the patient they may feel off-balance for a day or two, and that recurrence is common.", "Antiemetic before the manoeuvre helps the patient who is very nauseated."], "pitfalls": ["Doing an Epley without first confirming the side and canal with a Dix-Hallpike.", "Treating central positional nystagmus as BPPV.", "Prescribing betahistine or prochlorperazine instead of repositioning."], "hook": "Epley is a game of marble maze in the inner ear: tilt, wait, tilt again, until the stones drop back home.", "sources": ["https://litfl.com/john-epley/", "https://www.guidelinecentral.com/guideline/2775908/"]}, "befast": {"hist": "FAST (Face, Arm, Speech, Test or Time) was developed in the UK in 1998 by stroke physicians, ambulance staff and an emergency physician as part of a paramedic training package to speed recognition of stroke for thrombolysis. In 2017 Sushanth Aroor and colleagues at the University of Kentucky published in Stroke an analysis of 736 stroke patients showing that just over 14% did not present with FAST features; adding Balance and Eyes (BE-FAST) reduced the proportion missed to about 4%.", "etym": "A mnemonic acronym, deliberately an everyday word to signal urgency: Balance, Eyes, Face, Arm, Speech, Time.", "culture": "FAST became the basis of national public awareness campaigns, so it is one of the few clinical tools the public knows by name. BE-FAST was a response to the observation that posterior circulation strokes, with vertigo, ataxia or visual loss, are the ones most often missed, although a later prehospital study did not find that adding coordination and diplopia items improved detection.", "anat": "FAST items detect anterior circulation (carotid and middle cerebral artery) strokes, which produce contralateral facial and arm weakness and, in the dominant hemisphere, aphasia. Balance and Eyes target the posterior circulation: vertebrobasilar ischaemia affects the cerebellum (ataxia), brainstem (diplopia, nystagmus) and occipital lobes (hemianopia). Because the posterior circulation supplies relatively small, densely packed structures, deficits there can be dramatic in function but subtle on a quick FAST screen.", "context": "BE-FAST is a recognition tool for the public and triage, not a diagnostic test; in the ED it should trigger an immediate stroke pathway with NIHSS, glucose check and urgent CT or CT angiography. Large vessel occlusion scales such as RACE or LAMS sit alongside it in prehospital triage for thrombectomy centres, and thrombectomy windows now extend to 24 hours in selected patients. Many services still use FAST; BE-FAST improves sensitivity at the cost of more stroke mimics.", "pearls": ["Balance means sudden loss of balance or coordination, not chronic unsteadiness: ask about onset time.", "Eyes means sudden loss of vision in one or both eyes, or double vision.", "Record last known well, not when the patient was found.", "Check glucose before calling a stroke; hypoglycaemia is the classic mimic.", "Acute vertigo with a negative FAST still needs a central assessment (HINTS, gait)."], "pitfalls": ["Being reassured by a negative FAST in a patient with sudden vertigo, ataxia or visual loss.", "Treating the mnemonic as a full neurological examination.", "Losing time on a screening tool once the stroke pathway should already be activated."], "hook": "BE FAST because the back of the brain hides its strokes in your balance and your eyes.", "sources": ["https://uknow.uky.edu/uk-healthcare/neurology-residents-study-published-stroke-proposes-change-fast-mnemonic-stroke", "https://kiwix.lema.org/mdwiki_en_all_2024-03/A/FAST_(stroke)"]}, "ct-head-rule": {"hist": "Ian Stiell and colleagues derived the Canadian CT Head Rule in a prospective cohort of 3,121 adults with minor head injury in 10 Canadian emergency departments, enrolled 1996 to 1999, and published it in The Lancet in 2001. Patients had a GCS of 13 to 15 with witnessed loss of consciousness, definite amnesia or disorientation. The five high-risk criteria were 100% sensitive for need for neurosurgical intervention, and the full rule was about 98% sensitive for clinically important brain injury.", "etym": "Named after its country of origin; CT stands for computed tomography, from the Greek tomos, a slice.", "culture": "The rule came from the same Ottawa group as the Ottawa ankle and knee rules and the Canadian C-spine rule, part of Stiell's career-long programme of clinical decision rules aimed at reducing unnecessary imaging without missing important injuries. It deliberately excluded anticoagulated patients, children and those with seizures, an important limitation often forgotten in practice.", "anat": "The criteria proxy for intracranial haematoma: GCS below 15 at two hours reflects persisting brain dysfunction, repeated vomiting reflects raised pressure or brainstem irritation, and signs of basal skull fracture (Battle's sign, raccoon eyes, haemotympanum, CSF leak) indicate enough force to fracture the skull base. Age 65 or over reflects cerebral atrophy, which stretches bridging veins and allows subdural bleeding with less force, and dangerous mechanisms and long retrograde amnesia reflect greater energy transfer.", "context": "In 2026 the Canadian CT Head Rule remains the best-validated adult tool and underpins NICE head injury guidance (NG232, 2023), which adds its own criteria including lower thresholds for patients on anticoagulants. It applies only to adults with minor head injury and a defined loss of consciousness, amnesia or disorientation. For children, PECARN or the NICE paediatric criteria apply.", "pearls": ["High risk (for neurosurgery): GCS below 15 two hours after injury, suspected open or depressed fracture, any sign of basal skull fracture, two or more vomits, age 65 or over.", "Medium risk (for brain injury on CT): retrograde amnesia of 30 minutes or more, dangerous mechanism (pedestrian struck, ejection, fall from more than about 3 feet or five stairs).", "Check the inclusion criteria first: the rule does not apply without loss of consciousness, amnesia or disorientation, nor to anticoagulated patients.", "Reassess GCS at two hours rather than scanning the intoxicated patient reflexively; but scan if you cannot assess reliably.", "Give written head-injury advice and a responsible adult at discharge."], "pitfalls": ["Applying the rule to patients on anticoagulants, children or those with seizures, which it excluded.", "Forgetting that GCS 13 to 14 at two hours is itself a high-risk feature.", "Using it to justify no imaging in the patient with a focal deficit, which was an exclusion."], "hook": "Think of the rule as five red doors and two orange doors: walk through any one and you go to the scanner.", "sources": ["https://www.wikijournalclub.org/wiki/Canadian_CT_Head_Rule", "https://painepodcast.com/2019/11/14/53-ottawa-rules/"]}, "c-spine-rule": {"hist": "NEXUS (National Emergency X-Radiography Utilization Study), led by Jerome Hoffman and published in the New England Journal of Medicine in 2000, validated five low-risk criteria in 34,069 patients at 21 US centres, with 99.0% sensitivity for any cervical spine injury. Ian Stiell's group published the Canadian C-spine Rule in JAMA in 2001, and in 2003 a head-to-head study of 8,282 alert, stable trauma patients at nine Canadian hospitals, published in the New England Journal of Medicine, found the Canadian rule more sensitive (99.4% versus 90.7%) and more specific (40.4% versus 33.0%) than NEXUS.", "etym": "NEXUS is an acronym that also means a connection in Latin; 'cervical' comes from the Latin cervix, neck.", "culture": "The two rules became rival camps, sometimes framed in editorials as 'NEXUS versus the Canadian C-spine Rule', and the 2003 comparison by the Canadian authors was criticised for being run by the team that devised one of the rules. Both remain in use; UK guidance (NICE) adopts the Canadian rule for adults.", "anat": "The criteria encode the biomechanics of cervical injury: high energy mechanisms, age 65 or over (osteoporotic bone and stiff spondylotic spines that fracture at lower energy), and paraesthesias suggesting cord or root involvement. Midline tenderness points to the posterior bony elements, and the ability to actively rotate the neck 45 degrees each way is a functional test that a significant unstable fracture would usually prevent.", "context": "In alert (GCS 15), stable adults with neck trauma, these rules decide who needs imaging; when imaging is needed, CT has replaced plain radiographs in most adult trauma pathways. NICE NG232 (2023) uses the Canadian C-spine rule for adults. Neither rule applies to the obtunded, intoxicated or those with distracting injuries, and children need their own pathways.", "pearls": ["Canadian rule step 1: any high-risk factor (age 65 or over, dangerous mechanism, paraesthesias in the limbs) means image.", "Step 2: a low-risk factor (simple rear-end collision, sitting in ED, ambulatory at any time, delayed neck pain, no midline tenderness) allows safe range-of-motion testing.", "Step 3: if the patient can actively rotate 45 degrees left and right, no imaging is needed.", "NEXUS: no midline tenderness, normal alertness, no intoxication, no focal deficit, no painful distracting injury; all five must be present to clear.", "Never assess range of motion in someone with a high-risk factor."], "pitfalls": ["Clearing a patient who is intoxicated, has a GCS below 15 or a distracting injury.", "Forgetting the age 65 threshold, which catches low-energy falls in older adults.", "Ordering plain radiographs in high-risk adults when CT is the appropriate test."], "hook": "Canada asks three questions in order, danger, safety, then 'can you turn and look both ways?', like crossing a road.", "sources": ["https://www.2minutemedicine.com/canadian-c-spine-rules-superior-to-nexus-low-risk-criteria-for-detecting-cervical-spine-injuries-classics-series/", "https://www.wikijournalclub.org/wiki/National_Emergency_X-Radiography_Utilization_Study", "https://reliasmedia.com/articles/2691-nexus-vs-the-canadian-c-spine-rule-let-the-battle-begin"]}, "battle": {"hist": "William Henry Battle (1855 to 1936), surgeon at St Thomas' Hospital, London, described mastoid ecchymosis in his 1890 Hunterian Lectures at the Royal College of Surgeons, published that year in The Lancet and British Medical Journal as lectures on injuries to the head. He analysed 17 patients and identified the bruise over and in front of the mastoid as a strong indicator of a posterior fossa (skull base) fracture. Prescott Hewett had already noted the same bruising in 1861, and Battle acknowledged his work.", "etym": "An eponym after Battle; the American 'raccoon eyes' and British 'panda eyes' compare periorbital bruising to the dark eye patches of those animals, and 'ecchymosis' comes from the Greek ekchymosis, an outpouring of juice.", "culture": "Battle's sign is a classic example of an eponym going to the second describer: Hewett noted it nearly 30 years earlier. Battle himself also described periorbital bruising and CSF otorrhoea and rhinorrhoea in the same lectures, which together form the modern picture of basal skull fracture.", "anat": "Petrous temporal bone fractures tear vessels such as the posterior auricular and mastoid emissary veins, and blood tracks along fascial planes to appear behind the ear, often 24 to 48 hours later. In anterior cranial fossa fractures, blood tracks into the orbits and is contained by the orbital septum and its attachments, giving sharply demarcated bilateral periorbital bruising that typically spares the area beyond the orbital rim and occurs without direct eye trauma. Because these signs depend on blood tracking, they are often absent in the first hours.", "context": "In 2026 both signs remain high-risk features in the Canadian CT Head Rule and NICE head injury guidance, mandating CT head (usually with fine bone windows). They are specific but late, so their absence early does not exclude a basal skull fracture. Look for associated haemotympanum, CSF rhinorrhoea or otorrhoea, and cranial nerve palsies (facial and vestibulocochlear in temporal fractures).", "pearls": ["Look behind both ears; Battle's sign is easily hidden by the pinna or hair.", "Raccoon eyes are usually bilateral, confined by the orbital rim and without direct periorbital trauma.", "Otoscopy for haemotympanum is the earliest basal skull fracture sign, often present before bruising.", "Clear fluid from the nose or ear that leaves a halo on gauze suggests CSF; beta-2 transferrin confirms.", "Avoid nasogastric tubes and nasal airways in suspected anterior fossa fractures."], "pitfalls": ["Being reassured by absent bruising in the first few hours after injury.", "Confusing raccoon eyes with direct facial or orbital trauma, or with non-traumatic causes such as neuroblastoma or AL amyloidosis.", "Missing the cranial nerve examination in temporal bone fractures."], "hook": "The skull base fracture leaks its secret slowly: the raccoon puts on its mask and the bruise hides behind the ear a day later.", "sources": ["https://litfl.com/battle-sign/", "https://www.wikijournalclub.org/wiki/Canadian_CT_Head_Rule"]}, "pronator-drift": {"hist": "The arm drift test was described by the Italian neurologist Giovanni Mingazzini in 1913 in the Revue Neurologique ('Sur quelques petits signes des parésies organiques'): with arms outstretched, eyes closed, the paretic arm drifts down or the hand slowly sinks. Jean-Alexandre Barré described a leg sign in 1919; when Barré reproduced Mingazzini's arm and leg tests in 1937 without citing him, the arm test began to be misattributed to Barré as the 'Barré sign'.", "etym": "'Pronator' is from the Latin pronare, to bend forward or face downwards, describing the palm turning down; 'drift' describes the slow, involuntary movement.", "culture": "Barré is better known for Guillain-Barré syndrome, which he described with Guillain and Strohl in 1916; the misattribution of Mingazzini's arm test to him is a classic example of eponym drift. In many textbooks the test is still called Barré's sign.", "anat": "Corticospinal tract lesions produce a characteristic pyramidal pattern of weakness, affecting the extensors and supinators of the upper limb more than the flexors and pronators. When the arms are held forward with palms up and eyes closed, the weaker supinators lose the battle, so the hand pronates, the elbow flexes and the arm drifts down. Closing the eyes removes visual compensation; upward or outward drift with eyes closed suggests loss of proprioception or cerebellar dysfunction instead.", "context": "Pronator drift is one of the most sensitive bedside signs of subtle upper motor neurone weakness and is built into the NIH Stroke Scale (arm drift item). In the ED it helps detect mild hemiparesis in suspected stroke or TIA, intracranial mass or subdural haematoma, and it can be documented quickly for serial comparison. It supplements, never replaces, CT or MRI.", "pearls": ["Arms straight forward at 90 degrees (45 degrees if supine), palms up, fingers together, eyes closed, for 10 to 20 seconds.", "Watch the palm first: pronation precedes downward drift.", "Tapping the outstretched palms can unmask subtle drift.", "Upward drift or wandering suggests cerebellar or proprioceptive dysfunction rather than pyramidal weakness.", "Use it serially: progressive drift in a head-injured patient is an early sign of an expanding lesion."], "pitfalls": ["Testing with eyes open, which allows visual correction.", "Interpreting shoulder pain or rotator cuff weakness as pyramidal drift.", "Missing it because the arms are held for only a few seconds."], "hook": "Mingazzini's waiter cannot keep the tray level: with the eyes closed, the weak side turns its palm and spills.", "sources": ["https://litfl.com/giovanni-mingazzini/", "https://litfl.com/jean-alexandre-barre/", "https://en.wikipedia.org/wiki/Pronator_drift"]}, "rapd": {"hist": "Robert Marcus Gunn (1850 to 1909), a Scottish ophthalmologist at Moorfields Eye Hospital, London, described in 1902 a pupil that reacts better to consensual than direct light in unilateral optic nerve or retinal disease, in 'Functional or hysterical amblyopia' in The Ophthalmic Review. He noted that the pupil might constrict initially but then dilate despite continued light. Paul Levatin described 'pupillary escape' in disease of the retina or optic nerve in 1959, and the alternating swinging flashlight test became the standard way to show the defect.", "etym": "'Afferent' is from the Latin afferre, to carry towards (the brain); 'pupil' comes from the Latin pupilla, little doll, from the tiny reflection seen in another's eye.", "culture": "Marcus Gunn is also remembered for the jaw-winking phenomenon (a synkinetic ptosis), so 'Marcus Gunn' on a ward can mean two completely different signs. Neurologists have noted that the pupillary phenomenon is often explained incorrectly in teaching, as a pupil that dilates when light is shone into it, rather than a relative difference between the two eyes.", "anat": "Light entering either eye sends signals via the optic nerve, chiasm and optic tract to both pretectal nuclei and then both Edinger-Westphal nuclei, so normally both pupils constrict equally whichever eye is lit. If one optic nerve conducts less signal, swinging the light from the healthy eye to the affected eye reduces the total input, and both pupils dilate. The defect is relative: it compares the two afferent pathways, which is why bilateral symmetrical disease produces no RAPD.", "context": "In the ED an RAPD is a key objective sign in the patient with acute visual loss or eye trauma: it points to optic nerve (optic neuritis, ischaemic optic neuropathy, compression, traumatic optic neuropathy) or extensive retinal disease (central retinal artery occlusion, large detachment). It is not caused by cataract, refractive error or vitreous haemorrhage of modest size, or by cortical blindness. An RAPD after orbital trauma needs urgent ophthalmology and imaging, and an RAPD with sudden painless visual loss in an older patient should raise giant cell arteritis.", "pearls": ["Use a bright torch in a dim room, have the patient fix at distance, and swing briskly, holding 2 to 3 seconds on each eye.", "Watch for the initial movement as the light lands: dilation in the affected eye is the RAPD.", "You only need one working pupil: if one is fixed or dilated, watch the reactive pupil while swinging (reverse RAPD).", "Grade with neutral density filters if available, which helps track progress.", "An RAPD with a normal fundus suggests retrobulbar optic neuritis or compression."], "pitfalls": ["Swinging too slowly, allowing both pupils to redilate.", "Letting the patient focus on the torch, which causes accommodative constriction.", "Attributing an RAPD to cataract or refractive error."], "hook": "Swing the torch like a lie detector: the eye with the damaged cable lets the pupils relax when the light arrives.", "sources": ["https://litfl.com/marcus-gunn-pupil/", "https://pubmed.ncbi.nlm.nih.gov/14416133"]}, "horner": {"hist": "Johann Friedrich Horner (1831 to 1886), a Zurich ophthalmologist, published 'Über eine Form von Ptosis' in the Klinische Monatsblätter für Augenheilkunde in 1869, describing a 40-year-old woman with right ptosis, a small right pupil, slight enophthalmos and right-sided facial flushing and absent sweating. The sympathetic eye signs had already been shown experimentally by Pourfour du Petit in dogs (1727) and Claude Bernard in rabbits (1852), and described clinically by Silas Weir Mitchell in a soldier with a neck wound during the American Civil War.", "etym": "An eponym after Horner; 'ptosis' is Greek for falling, 'miosis' from the Greek meiosis, lessening, and 'anhidrosis' means without sweat (Greek hidros, sweat).", "culture": "In France and other French-speaking countries the condition is still called the Claude Bernard-Horner syndrome, recognising Bernard's earlier experiments. Horner used pharmacology even in 1869, noting that atropine dilated the affected pupil poorly.", "anat": "The oculosympathetic pathway has three neurones: from the hypothalamus down the brainstem and cervical cord to the ciliospinal centre at C8 to T2; preganglionic fibres then arch over the lung apex to the superior cervical ganglion; postganglionic fibres travel on the internal carotid artery into the cavernous sinus and orbit. Loss of sympathetic tone weakens the dilator pupillae and Müller's muscle, causing miosis and mild ptosis, and loss of sudomotor fibres causes facial anhidrosis in first- and second-order lesions. Because the lesion can sit anywhere from brainstem to orbit, the associated features localise it.", "context": "An acute painful Horner's syndrome in the ED is carotid artery dissection until proven otherwise, especially with neck pain, headache or minor neck trauma, and needs CT or MR angiography of the neck. Other key causes are lateral medullary (Wallenberg) stroke, Pancoast tumour, cervical cord lesions and cavernous sinus disease. Apraclonidine or cocaine eye drops confirm the diagnosis, but urgent vascular imaging should not wait for pharmacological testing.", "pearls": ["The anisocoria is greater in the dark, because the affected pupil cannot dilate; look for dilation lag in the first seconds after turning lights off.", "Ptosis is mild (1 to 2 mm) and often accompanied by slight elevation of the lower lid (upside-down ptosis).", "Painful Horner's plus headache or neck pain: think carotid dissection and image the neck vessels urgently.", "Look for the company it keeps: ipsilateral facial numbness and ataxia (lateral medulla), arm pain and wasting (Pancoast), or other cranial nerve palsies (cavernous sinus).", "Heterochromia suggests a congenital Horner's syndrome."], "pitfalls": ["Confusing physiological anisocoria (same in light and dark) with Horner's syndrome.", "Mistaking it for a third nerve palsy, where the pupil is large and the ptosis profound.", "Discharging a new painful Horner's without vascular imaging."], "hook": "Horner's eye is a sleepy, shrunken, dry-faced sentinel: when it appears with neck pain, look for a tear in the carotid wall.", "sources": ["https://litfl.com/horner-syndrome/", "https://www.revistas.ufrj.br/index.php/rbn/article/view/24977"]}, "asterixis": {"hist": "Raymond Adams and Joseph Foley described asterixis in 1949 in patients with severe liver disease and hepatic encephalopathy, at first calling it a tremor. Wanting a more precise term, they introduced 'asterixis' in a 1953 publication. Adams later helped spread the term as an editor of Harrison's Principles of Internal Medicine.", "etym": "Foley consulted Father Cadigan, a Jesuit classics scholar, who suggested 'anisosterixis'; Foley shortened it to asterixis, from the Greek a-, not, and sterixis, fixed position or support.", "culture": "The word was invented by a priest and shortened by a neurologist because the original was too hard to say. 'Liver flap' is the common but misleading nickname, since asterixis also occurs in uraemia, hypercapnia, drug toxicity such as phenytoin and structural brain lesions.", "anat": "Asterixis is negative myoclonus: brief lapses of muscle tone (electrical silence on EMG) interrupt a sustained posture, so the extended wrist briefly drops and then jerks back. It reflects dysfunction of motor networks that maintain posture, involving diencephalic, thalamic and cortical motor areas, caused by metabolic toxins such as ammonia or carbon dioxide or by drugs. Unilateral asterixis points to a structural lesion in the contralateral thalamus or motor pathways.", "context": "In the ED, asterixis is a quick clue that confusion is metabolic, typically hepatic encephalopathy, uraemia or carbon dioxide retention, and it is part of West Haven grading of hepatic encephalopathy. It prompts ammonia, blood gas, renal function and drug level testing, and a search for precipitants such as infection, gastrointestinal bleeding or constipation in cirrhosis. It is not specific for any single cause.", "pearls": ["Ask the patient to hold the arms out with wrists dorsiflexed and fingers spread for at least 30 seconds.", "Look for irregular, non-rhythmic flapping; a regular tremor is not asterixis.", "In patients who cannot hold the arms out, try squeezing your fingers (milkmaid's grip), or dorsiflexing the feet or protruding the tongue.", "Bilateral asterixis suggests metabolic encephalopathy; unilateral suggests a structural lesion.", "Asterixis tends to disappear in deep coma, as postural tone is lost."], "pitfalls": ["Calling it a liver flap and missing hypercapnia, uraemia or drug toxicity.", "Mistaking fine tremor or myoclonic jerks for asterixis.", "Testing for only a few seconds, missing intermittent lapses."], "hook": "Asterixis is the hand that keeps nodding off: the posture falls asleep for a heartbeat and wakes with a jerk.", "sources": ["https://en.wikipedia.org/wiki/Asterixis"]}, "chvostek": {"hist": "František Chvostek (1835 to 1884), a Moravian-born Austrian physician in Vienna, described facial muscle twitching on tapping the facial nerve in tetany in 1876 ('Beitrag zur Tetanie', Wiener medizinische Presse); Nathan Weiss described it independently in the early 1880s. Armand Trousseau (1801 to 1867) described carpopedal spasm induced by compressing the arm in latent tetany in his Clinique médicale de l'Hôtel-Dieu de Paris (1861).", "etym": "Both are eponyms; 'tetany' comes from the Greek tetanos, tension or convulsive tension, and 'main d'accoucheur' (obstetrician's hand) describes the hand posture in Trousseau's sign.", "culture": "Trousseau's name is attached to two signs: latent tetany and migratory thrombophlebitis in cancer. In 1867 he noticed phlebitis in his own arm and told his student he was lost; he died of gastric cancer months later, diagnosing himself with his own eponymous sign.", "anat": "Low ionised calcium lowers the threshold for sodium channel opening in nerve membranes, making peripheral nerves hyperexcitable. Tapping the facial nerve anterior to the ear (Chvostek) then triggers twitching of facial muscles, and inflating a blood pressure cuff above systolic for up to three minutes (Trousseau) adds ischaemia to the hyperexcitable nerve trunks, provoking flexion of the wrist and metacarpophalangeal joints, extension of the fingers and adduction of the thumb. Hypomagnesaemia and alkalosis, which lower ionised calcium, can produce the same signs.", "context": "In 2026 both signs are bedside clues to be confirmed with ionised calcium, magnesium, phosphate, PTH and an ECG for QT prolongation. Chvostek's sign is present in a substantial minority of healthy people (commonly quoted 10 to 25%) and absent in many with hypocalcaemia, so it is a weak test; Trousseau's sign is more sensitive and specific. They are particularly relevant after thyroid or parathyroid surgery, in massive transfusion, pancreatitis and hyperventilation.", "pearls": ["Tap the facial nerve about 2 cm anterior to the earlobe, below the zygoma; graded responses range from twitch at the angle of the mouth to contraction of the whole side of the face.", "For Trousseau, inflate the cuff above systolic pressure for up to three minutes and watch the hand.", "Trousseau's sign is the better test; a positive Chvostek alone means little.", "After thyroidectomy, perioral tingling plus a new positive sign warrants urgent calcium testing.", "Check magnesium; hypocalcaemia will not correct until magnesium is replaced."], "pitfalls": ["Diagnosing hypocalcaemia from a positive Chvostek in a normocalcaemic patient.", "Ruling out hypocalcaemia because Chvostek is negative.", "Relying on total calcium without correcting for albumin or measuring ionised calcium."], "hook": "Tap the cheek and the face winks, squeeze the arm and the hand becomes an obstetrician: low calcium makes the nerves jumpy.", "sources": ["https://litfl.com/chvostek-sign/", "https://en.wikipedia.org/wiki/Chvostek_sign", "https://litfl.com/armand-trousseau/"]}, "ottawa-ankle": {"hist": "Ian Stiell and colleagues at the University of Ottawa derived the Ottawa ankle rules and published them in the Annals of Emergency Medicine in 1992, aiming to reduce unnecessary radiographs in ankle injuries. The rules were refined and prospectively validated in JAMA in 1993, with an implementation study in 1994 and a multicentre trial in the BMJ in 1995. The derivation suggested the potential to reduce ankle radiography by roughly a third without missing clinically significant fractures.", "etym": "Named after Ottawa, the Canadian city where they were developed; 'malleolus' is Latin for little hammer.", "culture": "The Ottawa ankle rules are among the most widely validated and cited clinical decision rules in emergency medicine and became the model for the Ottawa knee rule, Canadian C-spine rule and Canadian CT Head Rule. Yet uptake has been uneven, as clinicians and patients often still expect an X-ray.", "anat": "The rules target the bony points that fracture under inversion and eversion: the posterior edge and tip of the lateral malleolus (fibula), posterior edge and tip of the medial malleolus (tibia), the base of the fifth metatarsal (avulsion by peroneus brevis), and the navicular. The posterior edges are chosen because ligaments attach to the anterior parts, so anterior tenderness reflects ligament sprain. Inability to bear weight reflects the functional loss caused by fractures.", "context": "The rules remain standard in 2026, with sensitivity close to 100% for clinically significant fractures in validation studies, and they have also been studied in children. They apply only to acute injuries in alert, cooperative patients. Point-of-care ultrasound can support assessment, and Lisfranc injuries, syndesmotic injuries and fractures of the fifth metatarsal base need specific attention.", "pearls": ["Ankle X-ray if malleolar pain plus bone tenderness at the posterior edge or tip (distal 6 cm) of either malleolus, or inability to bear weight four steps both immediately and in the ED.", "Foot X-ray if midfoot pain plus tenderness at the base of the fifth metatarsal or navicular, or inability to bear weight.", "Limping counts as weight-bearing.", "Palpate the whole length of the fibula to avoid missing a Maisonneuve fracture.", "Reassess at 5 to 7 days if still unable to weight bear."], "pitfalls": ["Palpating the anterior malleolus, where ligaments attach, instead of the posterior edge.", "Applying the rules to intoxicated, head-injured or distracted patients, or those with altered sensation.", "Forgetting that the rules do not rule out ligament injury."], "hook": "Four bones and four steps: press the back of the ankle bones, the fifth metatarsal and the navicular, then watch four steps.", "sources": ["https://painepodcast.com/2019/11/14/53-ottawa-rules/", "https://pubmed.ncbi.nlm.nih.gov/8114236/"]}, "ottawa-knee": {"hist": "Ian Stiell's Ottawa group derived the Ottawa knee rule in a study published in the Annals of Emergency Medicine in 1995, prospectively validated it in JAMA in 1996, and published an implementation trial in JAMA in 1997. The rule was 100% sensitive for clinically significant knee fractures and reduced knee radiography by roughly a quarter.", "etym": "Named after Ottawa; 'patella' is the Latin for a small dish, and 'fibula' the Latin for a clasp or brooch pin.", "culture": "The knee rule followed the ankle rule as part of a deliberate research programme to standardise imaging in emergency departments. It competes with the Pittsburgh knee rules, which rely on mechanism (blunt trauma or fall) and age.", "anat": "Fractures around the knee most often involve the patella, tibial plateau and fibular head. Isolated patellar tenderness, fibular head tenderness and inability to flex to 90 degrees each signal disruption of bone or the extensor mechanism, while inability to bear weight reflects functional loss. Age 55 or over reflects bone fragility.", "context": "The rule is still used in 2026 for adults with acute knee injury, with consistently high sensitivity for fracture. Ligamentous and meniscal injuries are not covered, and MRI is used for suspected internal derangement. Point-of-care ultrasound can detect effusion and lipohaemarthrosis.", "pearls": ["Knee X-ray if: age 55 or over, isolated patellar tenderness, fibular head tenderness, inability to flex to 90 degrees, or inability to bear weight four steps both immediately and in the ED.", "Isolated patellar tenderness means no other bony tenderness around the knee.", "A haemarthrosis within hours suggests ACL rupture, fracture or patellar dislocation.", "Check straight leg raise to exclude extensor mechanism rupture.", "Examine the hip in knee pain, especially in children and older adults."], "pitfalls": ["Applying the rule to patients with altered sensation or multiple injuries.", "Forgetting the age 55 threshold.", "Missing quadriceps or patellar tendon rupture because the X-ray is normal."], "hook": "Fifty-five, patella, fibula, flex, four steps: five keys to the knee X-ray door.", "sources": ["https://painepodcast.com/2019/11/14/53-ottawa-rules/"]}, "thompson": {"hist": "Franklin Adin Simmonds, a British orthopaedic surgeon, described the calf squeeze test for Achilles tendon rupture in The Practitioner in 1957 ('The diagnosis of the ruptured Achilles tendon'). Theodore Campbell Thompson, an American orthopaedic surgeon, observed the same finding in 1955 but published with Doherty in 1962 in the Journal of Trauma ('Spontaneous rupture of tendon of Achilles: a new clinical diagnostic test'). Thompson's cadaver experiments showed the foot still plantarflexed if the tear involved less than 90% of the tendon.", "etym": "Named after Simmonds and Thompson; the Achilles tendon refers to the Greek hero whose heel was his only vulnerable point.", "culture": "The test is known as Simmonds' test in the UK and Thompson's test in North America, a transatlantic priority split. Despite its simplicity, Achilles ruptures are frequently missed at first presentation, often because patients can still plantarflex using accessory muscles.", "anat": "The calf muscles (gastrocnemius and soleus) join to form the Achilles tendon, inserting on the calcaneum. Squeezing the calf deforms the muscle bellies and pulls on an intact tendon, causing passive plantarflexion. If the tendon is ruptured, no plantarflexion occurs. Tibialis posterior, flexor hallucis longus, flexor digitorum longus and the peronei can still produce weak active plantarflexion, which misleads examiners.", "context": "The test remains a cornerstone of diagnosis in 2026, alongside the Matles test (knee flexion) and palpable gap. Ultrasound or MRI can confirm partial ruptures or uncertain cases, and treatment decisions (functional rehabilitation versus surgery) depend on the patient and gap. Early immobilisation in equinus and referral are standard.", "pearls": ["Position the patient prone with feet over the edge of the couch, or kneeling on a chair.", "Squeeze the middle third of the calf and compare with the other side.", "Combine with the Matles test: with knees flexed to 90 degrees prone, the injured foot falls into neutral or dorsiflexion.", "Feel for a palpable gap 2 to 6 cm above the insertion.", "Partial ruptures may give a weakly positive or negative test; use ultrasound."], "pitfalls": ["Assuming no rupture because the patient can actively plantarflex.", "Squeezing the distal calf or tendon instead of the muscle belly.", "Missing the gap because swelling fills it."], "hook": "Squeeze the calf and the foot should bow: if it stays still, the heel cord has snapped.", "sources": ["https://litfl.com/simmonds-thompson-test/"]}, "scaphoid": {"hist": "The anatomical snuffbox takes its name from the habit of placing a pinch of powdered tobacco in this hollow to sniff it; the French term is tabatière anatomique. Scaphoid fractures became reliably diagnosable only after Röntgen's discovery of X-rays in 1895, and snuffbox tenderness became the classic clinical sign. There is no single eponymous describer of the sign.", "etym": "'Scaphoid' comes from the Greek skaphe, a boat or skiff, describing its shape; the older Latin name, os naviculare manus, also means little ship of the hand.", "culture": "Scaphoid fractures are among the most frequent causes of medico-legal claims in emergency medicine, because missed fractures can lead to non-union and avascular necrosis. Snuffbox tenderness was historically used as a stand-alone indication to immobilise and repeat radiographs.", "anat": "The snuffbox is bounded by extensor pollicis longus medially and extensor pollicis brevis and abductor pollicis longus laterally; its floor is the scaphoid and trapezium, and the radial artery runs across it. The scaphoid links the proximal and distal carpal rows, making it vulnerable in falls on an outstretched hand. Its blood supply enters distally from branches of the radial artery and flows retrogradely, so fractures of the waist or proximal pole can deprive the proximal fragment, leading to avascular necrosis.", "context": "In 2026, clinical signs (snuffbox tenderness, scaphoid tubercle tenderness and pain on thumb axial compression) are sensitive but not specific. NICE (NG38) advises considering MRI as first-line imaging for suspected scaphoid fracture rather than repeated plain films. Initial radiographs with scaphoid views remain standard, and a thumb spica or wrist splint is used until imaging clarifies the diagnosis.", "pearls": ["Test three signs: snuffbox tenderness, scaphoid tubercle tenderness and pain on axial compression of the thumb.", "Compare both sides; the snuffbox is often tender in normal wrists.", "Request dedicated scaphoid views, not just a standard wrist series.", "Immobilise any clinically suspected fracture even if X-rays are normal, and arrange MRI or follow-up.", "Proximal pole fractures carry the highest risk of non-union."], "pitfalls": ["Discharging without immobilisation or follow-up because the first X-ray is normal.", "Relying on snuffbox tenderness alone, which has low specificity.", "Missing associated injuries such as distal radius fracture or scapholunate ligament injury."], "hook": "The snuffbox hides a little boat with its fuel line at the bow: break the boat and the stern starves.", "sources": ["https://en.wikipedia.org/wiki/Anatomical_snuffbox", "https://www.iatrox.com/shared/68f490531557587903f7ec5b/nice-guidelines-for-suspected-schaphoid-bone-fractures-f7ec5b", "https://boneandjoint.org.uk/Article/10.1302/0301-620X.90BSUPP_I.0880083"]}, "cauda": {"hist": "The cauda equina was named in the 17th century, usually credited to the French anatomist André du Laurens (Laurentius), for its resemblance to a horse's tail. William Mixter and Joseph Barr's 1934 New England Journal of Medicine paper on rupture of the intervertebral disc showed that disc herniation could compress the spinal canal and its nerve roots, laying the foundation for understanding cauda equina syndrome. In England, the Getting It Right First Time (GIRFT) programme published a national suspected cauda equina syndrome pathway in 2023.", "etym": "'Cauda equina' is Latin for horse's tail; 'saddle anaesthesia' describes numbness in the area that would touch a saddle.", "culture": "Cauda equina syndrome is one of the most litigated conditions in spinal and emergency practice, because delayed diagnosis can leave patients with permanent bladder, bowel and sexual dysfunction. The GIRFT pathway aimed to reduce delays, but audits show variability in access to emergency MRI.", "anat": "The spinal cord ends at L1 to L2, and below it the lumbar and sacral nerve roots descend within the dural sac as the cauda equina. Large central disc herniations, tumours, infections or haematomas can compress multiple roots, especially the S2 to S5 roots that supply perineal sensation, bladder and bowel sphincters and sexual function. Loss of these functions reflects compression of the sacral roots, which lie centrally and are vulnerable.", "context": "In 2026, suspected cauda equina syndrome (back or leg pain plus bladder, bowel, saddle or sexual symptoms) requires emergency MRI; the GIRFT pathway asks for MRI within 4 hours of request where possible. Examination, including perianal sensation, anal tone and post-void residual on bladder scan, supports but cannot exclude the diagnosis. Early decompression improves outcomes, so imaging should not be delayed by examination findings.", "pearls": ["Ask directly about urinary hesitancy, altered stream sensation, saddle numbness, bowel changes and sexual dysfunction.", "Test perianal and saddle sensation with pinprick and light touch, comparing both sides.", "Measure post-void residual with a bladder scan; a large residual increases concern, but a normal volume does not exclude cauda equina syndrome.", "Rectal examination for anal tone and sensation has poor sensitivity; do it with consent and chaperone, and never let a normal result delay MRI.", "Bilateral sciatica is a red flag even without sphincter symptoms."], "pitfalls": ["Waiting for urinary retention before arranging MRI, by which time outcomes are worse.", "Relying on a normal rectal examination to exclude the diagnosis.", "Attributing urinary symptoms to opioids or pain without imaging."], "hook": "When the horse's tail is squeezed, the saddle goes numb and the bladder forgets: scan before it bolts.", "sources": ["https://en.wikipedia.org/wiki/Cauda_equina", "https://www.brownejacobson.com/insights/cauda-equina-syndrome-and-application-of-the-new-girft-pathway", "https://www.boa.ac.uk/resource/gifrt-national-guidelines-for-cauda-equina-syndrome-ces-a-guaranteed-success.html"]}, "cremasteric": {"hist": "Douglas Prehn, a US Navy urologist, described his sign in 1934 in the Journal of Urology ('A new sign in the differential diagnosis between torsion of the spermatic cord and epididymitis'): elevating the scrotum relieves pain in epididymitis but not in torsion. The cremasteric reflex in acute scrotal swelling was studied by Rabinowitz in 1984; in 245 boys with acute scrotal swelling, the reflex was absent in all 56 with torsion, and none of the 125 boys with an intact reflex had torsion.", "etym": "'Cremaster' comes from the Greek kremaster, a suspender; Prehn's sign is an eponym after Douglas Prehn.", "culture": "Prehn's sign was based on anecdotal observation, and later work, such as Roth and colleagues in 2018, found it positive in only a third of torsion cases, so it cannot exclude torsion. Case reports of torsion with a preserved cremasteric reflex show that even the best clinical sign is fallible.", "anat": "The cremasteric reflex is elicited by stroking the inner thigh; sensory fibres from the femoral branch of the genitofemoral nerve and the ilioinguinal nerve synapse at L1 to L2, and motor fibres of the genital branch of the genitofemoral nerve contract the cremaster, lifting the testis. In torsion, twisting of the spermatic cord disrupts the cremaster and its nerve supply, so the reflex is usually lost. Elevating the scrotum in epididymitis reduces tension on the inflamed epididymis and cord, easing pain, but in torsion it does not relieve ischaemic pain.", "context": "In 2026, testicular torsion remains a clinical diagnosis that requires urgent urology review and surgical exploration when suspected; salvage rates fall sharply after 6 hours. The TWIST score (testicular swelling, hard testis, absent cremasteric reflex, nausea or vomiting, high-riding testis) can help risk-stratify, with high scores prompting immediate surgery and intermediate scores ultrasound. Doppler ultrasound can support but not exclude torsion.", "pearls": ["Stroke the inner thigh and watch for testicular elevation of at least 0.5 cm on the same side.", "An absent cremasteric reflex in a painful, swollen testis strongly suggests torsion, especially in children.", "A present reflex makes torsion less likely but does not exclude it.", "Prehn's sign is unreliable; a negative sign never rules out torsion.", "Look for a high-riding testis with a horizontal lie and the bell-clapper deformity."], "pitfalls": ["Delaying surgical review while waiting for ultrasound in a high-probability case.", "Relying on Prehn's sign to diagnose epididymitis.", "Testing the reflex in a cold room or anxious patient, which can suppress it."], "hook": "Stroke the thigh and the testis should rise; if it stays down and hurts, the cord is twisted until proven otherwise.", "sources": ["https://litfl.com/douglas-prehn/", "https://www.bestbets.org/?p=6650", "https://www.bestbets.org/bets/can-a-positive-prehns-sign-be-used-to-diagnose-testicular-torsion/", "https://www.aafp.org/afp/2022/1200/pocg-testicular-torsion"]}};
Object.entries(DEEP).forEach(([k,d])=>{if(SIGNS[k]&&d.hook)SIGNS[k].hook=d.hook;});
function deepDive(id){
  const d=DEEP[id];if(!d)return "";
  const p=(t,v,icn)=>v?`<div class="sec"><h3>${t}</h3><p>${esc(v)}</p></div>`:"";
  const ul=(t,a)=>a&&a.length?`<div class="sec"><h3>${t}</h3><ul>${a.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>`:"";
  const host=u=>{try{return new URL(u).hostname.replace(/^www\./,"");}catch(e){return u;}};
  return `<div class="card dd"><div class="ddh"><span class="eyebrow">ER deep dive</span><span class="tag">history · anatomy · 2026 practice</span></div>
   ${p("In the department today",d.context)}${ul("Bedside pearls",d.pearls)}${ul("Common mistakes",d.pitfalls)}${p("The deeper anatomy and physiology",d.anat)}
   <details class="acc"><summary><span class="st"><b>History, name and story</b><span>Who, when, and why it's called that</span></span></summary><div class="acc-body">${p("History",d.hist)}${p("The name",d.etym)}${p("The story",d.culture)}</div></details>
   ${d.sources&&d.sources.length?`<div class="src">Sources: ${d.sources.slice(0,6).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(host(u))}</a>`).join(" · ")}</div>`:""}</div>`;
}
